BEGIN;

-- Immersió 1
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 1, '2019-07-20', '10:45:00', '11:30:00', 11.8, 45, 190, 61, 129, 15, 'bona', 22, 24, 10, 'Primera immersió en aigues obertes del curs d''OWD amb el CIB (Centre Immersió Biologia), amb la instructora Roser. Varem veure un pop, un congre i una morena. Còmode i divertida.', '2023-04-21 21:43:59', '2025-08-19 07:42:21');

-- Immersió 2
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 2, '2019-07-20', '12:35:00', '13:30:00', 13.5, 55, 190, 50, 140, 15, 'bona', 22, 24, 10, 'Segona immersió curs OWD amb el CIB també amb la instructora Roser. Varem veure un petit cranc.', '2023-04-21 21:45:53', '2023-04-21 21:45:53');

-- Immersió 3
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 3, '2019-07-21', '10:40:00', '11:40:00', 17.0, 60, 200, 50, 150, 15, 'bona', 21, 25, 10, 'Tercera immersió curs OWD amb el CIB. Nou instructor biòleg del CIB Andreu Llamas. Varem veure un congre i una morena junts, un corb marí i vam passar per un petit Arc de pedra.', '2023-04-21 22:14:56', '2023-04-21 22:14:56');

-- Immersió 4
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 4, '2019-07-21', '17:00:00', '17:56:00', 27.3, 56, 200, 30, 170, 15, 'bona', 22, 24, 10, 'Última immersió curs OWD amb el CIB amb instructor Andreu Llamas. Va ser la primera desde Vaixell. Varem baixar per el cap del vaixell. Varem veure una Barracuda, una morena i un congre. A la mar (Companya) li va entrar una mica de pànic i varem haver de pujar una mica més durant la resta de la immersió. Va ser immersió molt maca.', '2023-04-24 16:13:12', '2024-03-28 22:11:56');

-- Immersió 5
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 5, '2019-09-14', '12:00:00', '12:55:00', 19.6, 55, 190, 40, 150, 12, 'bona', 24, 26, 8, 'Immersió amb l''Edu i la Maria (pares escola Mireia). Va ser amb guia (Lander, vasc) de l''Andreas-diving. Immersió amb massa gent, grup massa gran i masses grups. Va estar bé, però massa massificada. Vàrem veure morenes (petites) i banquets de Sards i Salpes.', '2023-04-24 16:15:26', '2023-05-04 16:18:15');

-- Immersió 6
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 6, '2019-09-24', '14:00:00', '15:20:00', 13.6, 80, 200, 50, 150, 15, 'bona', 23, 26, 8, 'Immersió molt senzilla. Bussejant per l''escullera de blanes. Immersió lliure! sense instructor i sols amb el company del CIB, el gran Jordi Miró. Varem practicar la flotabilitat. Vàrem veure un pessebre submari i una formiga de ferro (estàtua submarina) que hi ha a la punta de l''escollera. Immersió molt llarga i molt anàrquica. Va ser molt xula per lo tranquila i còmode (temps, sense pressa, al nostre ritme). Totalment independent i sense dependre de res! Molt interessant.', '2023-04-24 16:17:49', '2023-04-24 16:17:49');

-- Immersió 7
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 7, '2019-10-10', '11:30:00', '12:20:00', 21.5, 50, 195, 2, 193, 12, 'bona', 22, 24, 6, 'La millor immersió fins el moment. Espectacular!! Amb la cosineta Núria Cardenyes! Brutal!! Immersió totalment lliure, sols sense ningú! sense centre! company de Núria que ens va deixar les ampolles. Vàrem veure molta vida! Banc de Barracudes, Bròtola, Escòrpores, Morenes, Congre, Dèntols, Bancs de Sards i Salpes. La millor immersió!', '2023-04-24 16:20:47', '2023-04-24 16:20:47');

-- Immersió 8
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 8, '2020-06-07', '09:19:00', '10:10:00', 8.1, 51, 200, 120, 80, 12, 'dolenta', 19, 21, 9, 'Immersió inici temporada 2020. La primera. Dia dolent, amb pluja, ventet i amb molt mala visibilitat. Oliver del Vanas Dive, ens deixa triar si entrar o no, com vulguem. Brutal, sense pressió decidim el grup reduït (Eduard, Monterrat, l''Oliver i jo) entrar. Alucino, primera experiència amb visibilitat penossísima. La desorientació i/o pèrdua està garantida. Oliver porta una llenterna amb flash que ens salva la pèrdua. Experiència brutal en acabar. La pujada a superfície i la sortida ens dona una panoràmica preciosa del litoral de Barcelona mentre ens cau una pluja forta i estem sols. Tornem per superficie aletajant cap a la sorra. Malgrat no veure res, el ritme, el tracte, l''hora ha estat fantàstic i una altre vegada he sortit molt emocionat. Vanas Dive molt i molt recomenable, Oliver molt bon paio igual que el seu ajudant Gallec. Molt satisfet!', '2023-04-24 16:28:06', '2023-04-24 16:28:06');

-- Immersió 9
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 9, '2020-07-01', '12:09:00', '13:01:00', 7.5, 52, 200, 130, 70, 12, 'bona', 21.19, 21, 8, 'Immersió senzilla amb molt bon temps. Aquesta vegada amb el company gallec Sandu, fem una immersió a l''escull de la Mar Bella, coneguda com la immersió dels "Cubs" ja que al final d''aquest espigó hi ha dos grans blocs en forma de cub submergits. Vàrem ser 8 bussejadors amb un de boia al darrera. Vàrem veure alguns petits Nudibranquis! Immersió còmode i xula, molt bona gent els companys, el meu company de busseig va ser en Julio, molt simpàtic. Com sempre, em vaig sentir molt còmode amb el Vanas Dive. Grans són.', '2023-04-24 16:32:01', '2023-04-24 16:32:01');

-- Immersió 10
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 10, '2020-07-04', '09:53:00', '10:41:00', 23.3, 48, 200, 70, 130, 15, 'bona', 21, 22, 8, 'Immersió maca. El Montiell hi vàrem arribar amb la Tritonera (Barca amb uns 14 bussejadors). El nostre guia Instructor (en David) força simpàtic. Vàrem baixar per el cap de la tritonera fins a uns aprox. 10m. Desde allà vàrem anar a buscar el punt més profund a uns 24m, i fent la volta vàrem anar pujant lentament. Destacable una praderia preciosa de posidònia on per sobre ella s''hi podien veure bancs de castenyoles, salpes i sargs. En David, ens ensenyava forces Congres. Va ser molt cómode fer la parada de seguretat en el cap, i em vaig sentir molt bé. La roca presenta una escletxa en tota ella, on ens hi podiem ficar per veure algún racó. Vaig veure petitet però per fi un mero. Immersió correcte, però NO espectacular. Tritón, bé, però ho vaig trobar un pél desorganitzat en els horaris. La tritonera xula, però una mica incòmode per saltar, també, una vegada més sóc Balena. Masses presses en general.', '2023-04-25 09:10:59', '2023-04-25 09:10:59');

-- Immersió 11
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 11, '2020-07-05', '13:05:00', '13:56:00', 8.6, 51, 200, 130, 70, 12, 'bona', 21, 22, 8, 'Immersió com si fós de platja, però hi vàrem arribar amb Vaixell (la Tritonera). Ha estat una immersió per seguir refrescant/recordant i sobretot per acompanyar a en Marc Satorras a fer el Bateig. Ho va fer molt bé!! Malgrat la poca profunditat i estar molt aprop de la platja hi havia una roca prou maca i al seu voltant força posidònia. Visibilitat excelent. Com sempre, Salpes i Sards. Vaig aprofitar per practicar buidat de màscara, aixi com recuperació de regulador. També, sensació de cap per amunt respirant i aguantat pel cap així com pràctica de flotabilitat. Lo millor de la immersió. La lliure disposició alhora d''entrar a l''aigua i les NO presses!!! (clar, hi havia bateigs, i a nosaltres ens van dir que fèssim el que volguèssim).', '2023-04-25 09:15:08', '2023-04-25 09:15:08');

-- Immersió 12
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 12, '2020-07-09', '10:13:00', '11:10:00', 15.2, 57, 200, 60, 140, 12, 'bona', 25.22, 26, 7, 'Immersió xula. Entre setmana, dia de festa, cotxe, i cap amunt. Blanes-Sub molt bé, perque és còmode. Avui he fet immersió amb instructor Félix i un altre noia. Correctes. Ritme per entrar desde platja super bé. En general, desde les meves sensacions, anaven massa ràpid, es movien massa ràpid dins aigua, després Fèlix m''ha comentat per poder arribar a la Seca i donar la volta. Pero bé, còmode. Molt content del consum així com del pes (he baixat un quilet). D''altre banda, aigua molt calenta per epoca any! Visibilitat molt bona, i lo més bèstia: Primera vegada que veig Nudibranqui Vaqueta Suissa! espectacular! gran i preciosa, sóla al costat del seu aliment, una esponja. També un Congre fora del cau!! gran! el Fèlix s''hi ha acostat perque no es movia i era degut a que pobre tenia una fil de pescar enrotllat! el Fèlix amb el ganivet, la pogut tallar, i aleshores el congre ha marxat. L''hem seguit una estona veient-lo nedar! brutal! La immersió no podia acabar millor quan la noia m''ha cridat per ensenyar-me un cavallet de mar!!! espectacular! color marró que es confón molt amb l''alga de roca. Però preciós!!. Immersió senzilla però xula. Llàstima que no he pogut filamar/fotografiar el que he vist!! mmmm potser cal anar pensant en càmara!? €€€€€ 🙁', '2023-04-25 09:17:59', '2023-04-25 09:17:59');

-- Immersió 13
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 13, '2020-07-19', '10:26:00', '11:28:00', 15.8, 62, 200, 50, 150, 12, 'bona', 25.22, 25, 6, 'Altra vegada. La Seca! Bona Immersió. Força gent, però espectacular. Guia Gabriel. Un tiu segur, i bon bussajador, es notava. Em van posar amb un Advanced com a parella, erem uns 8! força gent però em vaig sentir molt bé. Per proximitat, logística, Blanes i La Seca, Nacra ó Punta Sta. Anna són perfectes. De Sant Pol són 25min. per tant, molt còmode. M''ho vaig passar molt bé altre vegada. Coses a destacar d''aquesta immersió: Espectacular banc de Sards i Seitons. Preciós! En Gabriel (instructor) ens va ensenyar el Canó d''algun Derelicte enfonsat fa molt de temps, i que vaig sentir-me també molt còmode baixant a 6kg de llast! 5Kg de cinturó + el Quilet que porto al Jacket. Bona Immersió!', '2023-04-25 09:22:07', '2023-04-25 09:22:07');

-- Immersió 14
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 14, '2020-07-25', '16:13:00', '17:05:00', 16.1, 52, 210, 70, 140, 12, 'bona', 25.2, 27, 6, 'La meva primera Col.lectiva amb el CIB! Molt bé, genial. No hi va anar ningú del meu curs (OWD244), pero vaig tornar a veure els profes! Andreu, Toni, Jordi i Roser. La cala la varen fer la Roser i el Jordi. Uns cracks, ja sabem. Vàrem fer dos grups (els de més i menys experiència), vaig anar amb els de menys experiència i només vam ser el Jordi (presi), una noia i jo! amb el Jordi va ser brutal, super tranquil xino-xano per la caleta, vàrem arribar fins a una estructura metàlica que representaba la Rosa dels Vents (en la immersió del curs de l''any passat no la vaig veure!). Allà vàrem veure un congre i el jordi va localitzar un nudibranqui super petit, blau, molt xulo. Vaig veure diria un parell de Meros. Va estar super bé tornar a parlar molt amb la Roser, i retrobar-me amb els profes del CIB. Super bé!!!', '2023-04-25 09:25:32', '2023-04-25 09:25:32');

-- Immersió 15
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 15, '2020-07-29', '11:53:00', '13:04:00', 18.6, 71, 200, 50, 150, 15, 'bona', 26.2, 30, 6, 'Segona Col.lectiva amb el CIB!. Vaig coincidir amb el Sergi (OWD244). Es van formar dos grups. Els profes CIB que vàren venir, van ser Roser i Toni. Vaig anar amb el grup del Toni Arcas amb uns Opens acabats d''estrenar. La immersió va estar espectacular. Molta estona 71min. vaig durar! altres vàren haber de sortir abans, Molt satisfet de seguir amb 6kg i aguantant molt bé fins al final. Molt i molt guapa. Vàrem veure molt de ''bitxu''!! Exemplars gegants de Sards Imperials, Molta morena. Molta. Déntols, molts i molt grans i per fi un pop preciós!!! nedant i camuflant-se. Tossa és brutal. Sempre. Mai decepciona. Centre, just, sense dessalar, sense vestuaris, res de manguera, fallaba tarja de crédit, per aparcar fatal. Centre gents cómode, tot i això, Tossa és la immersió reina. Impressionant.', '2023-04-25 09:28:53', '2023-04-25 09:30:27');

-- Immersió 16
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 16, '2020-08-14', '17:22:00', '17:58:00', 7.7, 36, 200, 130, 70, 12, 'moderada', 27.26, 31, 6, 'Aprofitament d''immersió. Una pena, debia ser la ruta dels tres Arquets, i per falta de quòrum es va suspendre. Dídac, de blanes sub, per no avisar-me em va deixar acompanyar un bateig per la punta de Sta. Anna. Immersió molt evitable. Va ser pobre, aburrida, Parts i experiència que en trec? Adonar-me, per exemple, que es busseja molt malament i de manera incòmode quan es passa calor! en vaig passar. L''aigua estava a 27ºC i al no baixar fons, a aquesta temperatura i tot equipat, va ser molt incòmode, val la pena enterar-se de la temperatura per poder planificar el tipus de roba a utilitzar. Part positiva? jeje, que una vegada més poso el cap sota aigua per practicar i que la immersioneta em va sortir gratis perque Dídac no em va cobrar ja que no em va avisar per anular la immersió per falta de quòrum, i aleshores em va regalar l''acompanyament del bateig.', '2023-04-26 07:07:32', '2023-05-04 16:18:39');

-- Immersió 17
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 17, '2020-10-04', '13:42:00', '14:20:00', 5.4, 38, 240, 160, 80, 12, 'bona', 20, 22, 7, 'Una altre acompanyament de bateig! Aquesta vegada, molt intencionat amb el gran Jordi Balasch. Un crack! la fantàstica Eli (oceanògrafa) de Plàncton Diving ens va impartir teoria sobre la fauna de la zona. Ens va estar explicant durant força estona les característiques de tota aquesta fauna. Realment va ser una introducció a la biología marina en tota regla. Fantànstic. Respecte el bateig i en vista d''acompanyant, crec que l''amic Balasch va tenir la gran sort de topar amb Plàncton Diving. Estavem sols, amb tota la tranquilitat i el temps del món. Va ser molt cómode. L''entorn era preciós. La visibilitat va ser extraordinària, i el paràtge verge i salvatge espectacular. Me''n porto un esplèndit record. L''experiència que en trec és que una vegada més, el més d''Octubre demostra que és un gran moment per disfrutar d''un busseig tranquil i encara assumible.', '2023-04-26 07:10:51', '2023-04-26 07:10:51');

-- Immersió 18
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 18, '2020-10-18', '11:15:00', '12:14:00', 8.4, 59, 180, 70, 110, 12, 'bona', 19.18, 20, 7, 'Immersió de nou amb Vanas Dive. El gran Oliver. Molt bé. Només erem 4 persones, el gran Kike (59) va ser el company d''immersió. Com sempre, ritme d''entrada a l''aigua tranquil i còmode (tipus sóc Balena). Vàrem fer les plataformes enfonsades que hi ha just al final de l''escull de davant del centre (Mar Bella). Malgrat vèncer un bon tram de molta bruticia (especialment llauna), un pop ben tranquil es va deixar veure en el seu cau. La immersió va ser la coneguda com a ''Plataformes enfonsades''. Son unes grans estructures enfonsades i aguantades per quatre columnes amples. La sensació d''estar sota el gran sostre de la plataforma ens va donar un ambient i atmosfera misteriosa (no massa llum i poca visibilitat). Va ser guapíssim. A la galeria hi ha mini videos per gentilesa del gran Kike. Com sempre super bé i còmodes amb l''Oliver de Vanas.', '2023-04-26 07:14:47', '2023-04-26 07:16:06');

-- Immersió 19
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 19, '2021-05-12', '11:28:00', '12:16:00', 5.7, 48, 200, 130, 70, 12, 'bona', 15, 18, 9, 'Estrena temporada 2021! Per fi, amb moltes ganes d''estrenar el nou Regulador MC9 de Cressi. Bé, ja conegut per anteriors immersions de lloguer. M''ha funcionat com m''esperava. Bona demanda d''aire, una autocrítica però en que la mossegadora s''escapa amb massa facilitat, si et despistes trobo que s''escapa massa fàcil de la boca. La immersió ha estat molt senzilla, només era el contacte amb l''aigua després de 5 mesos. Una bona prova per veure l''aillament tèrmic del nou Cressi Fisterra. Han estat 48min d''mmersió amb l''aigua a 15ºC !. Immersió totalment suportable a aquesta temparatura malgrat m''ha servit molt per comprobar que a partir dels 40min començava a notar fred!. Respecte a sorpreses en la immersió, destacar dues sèpies xulíssimes que el Sandu descobreix enterrades a la sorra i les fa sortir delicadament. També, al ser primavera s''observen molts peixos petits (sards) dels que després veurem més grans a ple Estiu!. Bones sensacions i feliç d''arrancar temporada! Com sempre, amb Sandu i Oliver de Vanas super bé!', '2023-04-28 20:46:25', '2023-04-28 20:46:25');

-- Immersió 20
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 20, '2021-05-30', '11:31:00', '12:35:00', 13.5, 64, 190, 70, 120, 15, 'bona', 17.16, 20, 7, 'Primer col·lectiva de l''any amb el CIB! Vàrem ser tres grups. Els instructors Toni Arcas, Jordi Regàs i Adrià. En Jordi em va dir que anès amb Adrià. Erem l''Adrià i dos companys més en Nacho (veterà del CIB) i un nano acabat de fer l''OWD però molt bo. La immersió va ser correcte. L''aigua freda però aguantable perfectament amb el Cressi Fisterra! de nou, el traje molt bé. Vàrem veure dos pops molt bonics un d''ells gents poruc i l''altre si i fins i tot em va expulsar una mica de tinta. Vàrem veure també tres morenes petites. La visibilitat no massa bona. Després en Toni Arcas em va comentar degut al Zooplàncton típic dels mesos de Primavera. Sempre passa. Vaig tenir una mica de malt de cap per les cervicals (nit anteriror coixí i sofà de Sant Pol! Grrrrr!!) però bé, vaig disfrutar bastant malgrat no va ser la millor immersió de Tossa. Content d''haver aguantat força bé amb cinturó de 6kg més el quilet repartit per les butxaques del jacket. Una altre immersió al sac!', '2023-04-28 20:51:17', '2023-05-04 16:17:32');

-- Immersió 21.1
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 21.1, '2021-06-05', '09:19:00', '09:45:00', 7.7, 26, 200, 130, 70, 12, 'dolenta', 21.2, 23, 8, 'Horrorós. Desde l''Open a aquell dia a la piscina que no havia tornat a tenir una mica d''agobiament. Aquesta vegada va ser per la dolentíssima i continua mala visibilitat. Aigua-xocolata, amb tres companys del CIB després d''aletejar també amb cert esforç per la mar de fons que existia, vàrem decidir treure el cap i abortar temporalment l''immersió sortint a superfície. No passava res ja que era un tipus d''immersió que ho permetia per la poca profunditat i per la necessitat d''anar treient brutícia amb les bosses i entregar-la a l''Irene (noia que ens esperava a l''escull per recollir el que li anavem passant). Era complicat treure brutícia perque no es veia res!! Desde el meu entendre va ser que el problema es que amb l''Elena (simpàtica i bona bussejadora) i en Pol (jove) no vàrem saber sortir de la zona de dolentíssima visibilitat per anar a alguna zona amb millor visibilitat (probablement sortint de l''escull tal i com varen fer els altres grups). Això, finalment ens va agobiar (almenys jo em notava com cada cop l''agoviament em creixia en l''estat general) pensant que el millor era treure el cap a superficie de nou. Indicant-ho a en Pol, aquest em va dir el mateix i que li semblava bé i vàrem sortir junts "abandonant" a la pobre Elena, sabent que el protocol (l''haviem parlat) era que si en 30-40 seg. algú es perdia, automàticament sortia a superfície per localitzar-nos desde la mateixa. I axí va ser. En nedar lentament durant 10min a l''estar a la "deriva", l''Elena va dir que abandonava, i jo després de perdre les ulleres Cressi Grogues!!! l''Elena me les va deixar, i amb en Pol vàrem tornar a baixar fent una estoneta més i anant cap a una zona on la visibilitat va guanyar una mica més. Aquesta part és la segona immersió consecutiva que vàrem fer i explicada a la següent. La 21.2 !!', '2023-04-28 20:58:33', '2025-06-12 11:26:12');

-- Immersió 21.2
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 21.2, '2021-06-05', '10:06:00', '10:28:00', 7.6, 22, 130, 70, 60, 12, 'dolenta', 21.2, 23, 8, 'Efectivament, després de lo explicat a la immersió 21.1, aquesta següent mini-inmersió, es va convertir en inmersió repetitiva! (no molt aconsellable) ja que el temps a superfíce no va superar entre 10 i 15min abans de tornar a submergir-nos. De tota manera, el perill era mínim ja que la profunditat de la primera inmersió, així com la que anavem a tornar a fer era molt petita i per sota els 10m. Aquesta vegada, després de que l''Elena No volgués tornar a entrar, com deia, em va deixar les ulleres i gràcies a en Pol que va insistir, vàrem tornar a bussejar una estoneta més. Aquesta vegada en Pol va sortir de l''espigó i vàrem millorar una mica la visibilitat permetènt-nos inclús recollir alguns plàstics i bussejar una mica més còmodes.', '2023-04-28 21:17:34', '2025-06-12 11:30:00');

-- Immersió 22
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 22, '2021-06-13', '12:09:00', '13:10:00', 5.8, 61, 200, 80, 120, 12, 'bona', 21.19, 26, 8, 'Immersió senzilleta, tranquila de platja amb l''Edu. Preparant les futures immersions de Sant Joan (Camping). Va ser super relaxada i tranquila, només l''Edu i el guia (no hagués calgut), Vicente, un paio força simpàtic i que ens va explicar que s''estava treient amb una compaña (Argentina molt simpàtica) el Divemaster a Poseidón per exercir oficialment de guies. Amb el Vicente vàrem practicar molt breument flotabilitat (Exercici inspiració i expiració), recuperació de regulador i recolocació buidat de màscara. Va estar molt bé. Després, la passejada va ser molt tranquila. Vàrem veure una sèpia així com un Pop mitjanet i molt maco. Veure nedar el Pop és molt xulo. Finalment, i per distreure''ns i allargar una mica més la immersió, vàrem passar per una mini-xemenèia qui hi ha, petiteta, però xula. Altre vegada vaig tenir una mica malt de cap/cervicals degut a que la nit anterior vàrem estar a Sant Pol, sofà i llit!!!? Grrrrrrrrrrrr!!! però suportable.', '2023-04-28 21:20:38', '2023-05-04 16:21:39');

-- Immersió 23.1
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 23.1, '2021-06-19', '11:32:00', '12:35:00', 10.7, 63, 200, 100, 100, 12, 'bona', 21.19, 26, 7, 'Immersió espectacular! La millor desde 2019. Impressionant. Amb la Roser (instructora CIB). Erem la Queralt, l''Alex, el Roger i Jo. Recorregut preciós per l''illa Mateua. La Roser (brutal!!!) ens va portar poc a poc rodejant TOTA l''illa aturant-nos i passant per dos túnels maquíssims de l''Illa. El primer (la mar estava molt plana i sense corrent!) ens va permètre, treure el cap per una mini càmara d''aire. Espectacular! els túnels són xulíssims i veure desde dins la sortida del túnel amb el color blau és impressionant. Vàrem veure molta cosa. La Roser és una crack! mostrant-nos ple de vida. Biologia!!! Vàrem veure: Llagosta!!!!, pop, mini-morena, mini vaqueta suissa (Nudibranqui logo CIB) castanyoles, salpes (banc) estrelles de tot tipus, corall vermell!!!! increible. Molt i molt bé. Em vaig sentir súper cómode, sense malt de cap i amb molt molt bones sensacions. Espectacular, en acabar immersió de 63min!!! encara ens quedaba 100bar i vàrem decidir fer immersió continuada (23.2). Espectacular!!!', '2023-04-28 21:24:20', '2023-04-28 21:24:20');

-- Immersió 23.2
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 23.2, '2021-06-19', '12:42:00', '13:05:00', 10.9, 23, 100, 40, 60, 12, 'bona', 21.18, 26, 7, 'Immersió espectacular! També. Sí! vàrem decidir, amb el que ens quedaba d''aire, fer immersió en aquest cas sortint, abandonant l''illa i tirar (Roser Brújola) cap a fora en camps de posidónia preciosa!! a Mar obert increíble la sensació de llibertat. Molt i molt content de practicar busseig nadant d''esquena tipus santat i practicant! per primera vegada vaig controlar en aquesta posició bastant bé la flotabilitat! va ser brutal!! Molt i molt content. M''ho vaig passar molt i molt bé!! acollonant.  ATENCIÓ!!! VA SER LA ÚLTIMA IMMERSIÓ DEGUT A PERFORACIÓ D''OÏDA. EN TRÀNSIT A DIA D''AVUI (28-JUNY-2021) NO SÉ QUAN PODRÉ TORNAR A FER-NE UNA ALTRE!!!! 🙁', '2023-04-28 21:27:24', '2023-05-04 16:15:08');

-- Immersió 24
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 24, '2021-09-12', '12:09:00', '13:10:00', 16.0, 61, 200, 50, 150, 12, 'bona', 25.2, 23, 7, 'TORNADA A L''AIGUA DESPRÉS DE LA PERFORACIÓ DEL TIMPÀ! Immersió lliure a Blanes. Vàrem pujar finalment l''Àlex (CIB) i l''Enric un amic d''en Xavi (CIB). En Xavi (CIB) i la Sílvia (CIB) finalment no van poder venir tot i que inicialment també hi havien de ser. Gràcies a l''Enric (ex instructor de Maldives!) l''Àlex i jo ens vàrem sentir molt segurs. Ell va liderar clarament la immersió i ens va fa de guia. Vàrem arribar fins la Seca! Mooooooolt bé en Xavi. Un nano molt maco i bon bussejador. A nivell de peix, malgrat les fotografíes que va enviar l''Enric (veure galería fotogràfica) no en vàrem veure massa. La visibilitat era força bona tot i existir zones més tèrvola. La temperatura de l''aigua amb un important canvi i contrast a partir de -10m cap aball. És a dir, d''entre 11m y 16m baixava a 20ºC mentre de 0m a 5m estava a 25ºC. Per tant termoclina notoria. Respecte l''orella dreta, destacar que vaig estar controlant constantment el descens i de manera vertical, mirant cap amunt a ser possible per facilitar la compensció. Va anar prou bé, perque no em va fer molèstia excessiva, tot i no trobar-me al 100%, a l''anar tant lent de 0m a -10m vaig anar compensant prou bé i per tant en acabat no vaig sentir cap molèstia. Molt molt content! Mantenir aquesta dinàmica per tal de controlar sempre aquest claríssim punt feble que m''he descobert. L''oïda dret!!!  Contentíssim de la immersió. Anar per lliure és increíble. Brutal. Ens ho vàrem passar molt bé.', '2023-04-28 21:31:37', '2023-05-04 16:22:09');

-- Immersió 25
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 25, '2021-09-18', '12:48:00', '14:08:00', 9.0, 80, 200, 70, 130, 12, 'moderada', 22, 23, 7, 'Immersió lliure. Llarga! És clar, de poca profunditat. Illa Mateua, molt còmode i senzilla. Altre vegada amb l''Alex (CIB), i aquesta vegada es va apuntar també la Sílvia (CIB). De nou, pujant amb el cotxe d''AGFA (Zafira) desde Barcelona, vàrem anar fins a l''Escala, per assegurar immersió fàcil i senzilla. Mateua. Curiosament tot i entrant amb molta lentiud (Força estona per vestir-nos i entrar a l''Aigua), els primers minuts de la immersió em vaig sentir una mica agoviat, un pél claustrofóbic i amb ganes de tornar a superfície immediatament. No sé perqué? potser era l''aigua un pél massa calenta (a poca profunditat) i pel dolor de cervicals que arrastrava desde la nit anterior. Tot i així, passats 5min d''immersió, vaig començar a sentir-me millor fins a disfrutar força la resta de la mateixa. Vàrem veure poc animal, una moreneta (aixó sí, amb la seva clàssica gambeta de companyia!) i forces vaquetes suïsses (nudibranqui). Els tunels com sempre xulos malgrat foscos perque només disposavem del focus de l''Alex. La visibilitat no massa bona, però l''onatge i les currents molt dèbils i per tant els moviments vàren ser molt còmodes. Després d''un parell de voltes a l''illa, vàrem fer una mica d''orientació amb la brújula de l''Alex anant cap a praderia de posidónia. Cap al final de l''immersió i per poca profunditat vàrem sortir a superfície i al quedar-nos aire vàrem voler seguir una mica més però vàrem tenir que abortar la immersió perque l''Alex no va poder tornar a baixar degut a molèsties importants a l''oïda. Vàrem quedar-nos a dinar a Mateua dive (molt bé) i vàrem marxar cap a la tarda. Desde les 7h del matí fins a les 20h que arribava a Barcelona. Gràcies Núria per deixar-me disfrutar d''aquest dia! hehehe. Salut i bombolles. Fins la propera!', '2023-04-28 21:37:02', '2023-04-28 21:37:02');

-- Immersió 26
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 26, '2021-10-03', '10:53:00', '11:35:00', 5.4, 42, 200, 140, 60, 12, 'moderada', 23, 23, 7, 'Immersió a Plàncton Diving, com l''any passat i acompanyant a el segon bateig de l''amic Jordi Balasch. Grandiós. Malgrat certa mar de fons amb corrent i no molt bona visibilitat, la immersió va ser molt senzilla, relaxant i agradable. Ens vàrem trobar molt bé. Aquesta vegada en el bateig s''hi va afegir un nano xilé i com a guia de busseig (a part de la gran Eli) s''hi va afegir el Jose, tot un perssonatge. L''Eli va estar més per nosaltres, i en Jose amb el company xilé (de pare Marine). Vàrem veure sards i salpes així com un pop petit dormint al seu cau. Espero convèncer a l''amic Balasch perque es tregui l''Open Water i fer junts de tant en tant inmersions senzilles i agradables. Sería preciós!', '2023-05-04 14:25:33', '2023-05-04 14:28:26');

-- Immersió 27
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 27, '2021-10-12', '10:35:00', '11:18:00', 18.7, 53, 200, 60, 140, 12, 'moderada', 19, 21, 7, 'Immersió amb Unisub. Amb el gran Edu Ferrer (Escola Mireia) vàrem planificar una immersió a Medes. Per l''estat de la mar i pel vent de Nord (Tramuntana), el centre va decidir bussejar a el punt conegut com a ''Tascó Petit''. Després de que programés l''Immersió amb la gent d''Unisub, vàrem quedar a les 9h al centre per embarcar i entrar a l''aigua cap a les 10h. En el barco hi anava força gent però en la immersió al ser OW vàrem ser l''Edu, el monitor (una noia) i jo. Entrant a l''aigua amb el salt tipus ''pas de gegant'' vàrem baixar per el cap fins a uns 8m de profonditat on després d''estabilitzar-nos vàrem començar el passeig. Només baixar vàrem veure un Nero gegant, aproximadament d''1m de longitud. Val a dir, que malgrat veure molts Neros, les espectatives de Medes vàren quedar una mica frustrades ja que malgrat haver-hi força vida, em va donar la sensació de veure menys del que m''esperava. La visibilitat no va ser excel.lent i malgrat sentir-me molt còmode en tota la immersió, la realitat és que sincerament no em va semblar una experiència espectacular pel preu (52€ posant jo tot l''equip). Tot hi així, evidentment haig d''aprovar la immersió i evidentment tornaré de ben segur a bussejar per aquest arxipèleg.', '2023-05-04 14:30:29', '2023-05-04 14:30:29');

-- Immersió 28
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 28, '2021-10-27', '11:20:00', '12:13:00', 7.8, 53, 200, 100, 100, 12, 'bona', 18, 21, 7, 'Immersió a Barcelona. M''encanta, és com sempre especial i comodíssima. El millor centre, tracte desde que vaig iniciar-me al busseig. Oliver, Nico, Senda, Gabi... no fallen! super super ben parits. M''ho vaig montar per anar entre setmana. Dimecres. Finalment només vaig bussejar jo amb el Gabi (Venezolano). El Nico (nano jove) va anar amb un Guiri per fer un bateig. Vàrem repetir la immersió de les Plataformes. El Gabi brutal, una passada de bussejador, súper tranquil, lent amb un trimat brutal. Vàrem passejar molt lentament fent el recorregut complert entrant per l''escull just en front del centre Vanas dive i entrant per l''esquerra (deixant l''escull a la nostra ma dreta). Una vegada fent-lo tot, vàrem arribar a la primera plataforma, després a la segona, per girar i tornar per l''escull però per l''altre costat. Vàrem estar a poca profunditat amb gents de fred. El Gabi una passada mostrant-me com carregaba el xaleco amb l''ampolla ell sol posant-s''ho a l''inversa i per davant. Brutal. D''altre banda, vàrem veure un pop maquíssim enganxat a una de les columnes de la primera plataforma. Pobret, por que tenia, va canviar de color i ens va vomitar una espesa tinta negre. El gran d''en Gabi, em va cambiar d''ordre els latiguillos de la segona etapa (principal i octopus) per tal de que em fos més fàcil per colocar-ho en cada inmersió i per facilitar la comoditat en la colocació de la segona etapa principal (regulador blau-negre). Vanas el millor centre!!!', '2023-05-04 14:34:31', '2023-05-04 14:34:31');

-- Immersió 29
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 29, '2021-11-06', '12:14:00', '13:06:00', 16.4, 52, 200, 60, 140, 12, 'bona', 17.15, 17, 7, 'Immersió a Mar Menuda degut al canvi que el CIB va haver de fer per les condicions meteorològiques. Sí! bufava molta tramuntana i segons geografía, la Mar Menuda a Tossa queda prou protegida per els vents del Nord i acostuma a ser una bona alternativa en dies de tramuntana. Així va ser, impressionant, només arribar ningú a Tossa!! Aparcament... el que vulguis, gratuït, sense gent! una passada. Sensació evidentment d''estar bussejant fora de temporada. Un luxa! Malgrat tot, la part més desagradable és el fred que fa al sortir i/o al cambiar-te abans i post immersió. La immersió com a tal va ser correcte. Amb un moment de fort onatge/corrent en el moment de saltar el freu (braç rocós submergit que connecta la platja amb l''illa). Una vegada salta''t el freu, i al tornar a agafar més profunditat, en l''esplenada coneguda com a l''Aquari, la immersió va ser més còmode. A nivell de fauna, vàrem veure alguna morena i sobre tot amb el gran Jordi Clua (i el seu amic Joan, del GROC i CIB) vàrem poder disfrutar d''una espectacular Escòrpora! veure video a Galeria. Vaig pujar desde Barcelona amb la Síliva (CIB), super bé. Vàrem reunir-nos amb socis del CIB (Jordi Clua, Joan, Ruben i unes noies estrenades d''OW) i l''únic instructor que va venir va ser l''Andreu! que ens va fer xerrada sobre biologia marina. Dia espectacular en tots els nivells!! preciós.', '2023-05-04 14:38:16', '2023-05-04 14:38:16');

-- Immersió 30
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 30, '2022-05-07', '11:14:00', '12:20:00', 8.8, 66, 200, 40, 160, 12, 'bona', 16.15, 18, 9, 'Primera immersió temporada 2022! Espectacular. Amb unes ganes molt fortes de tornar a l''Aigua, després d''unes setmanes d''anar controlant la temperatura de l''Aigua, gràcies a l''experiència de l''any passat, vaig decidir fer immersió a l''observar que la temperatura de l''aigua rondava entre els 15 i els 16ºC i sabia que el Fisterra amb protecció tèrmica i guants em permetria realitzar immersió còmoda amb un mínim de 40 minuts. Així va ser! no vaig patir gents de fred! La immersió va ser amb els companys de Vanas Dive. Oliver, de nou, brutal supercòmode i excel.lent tracta com sempre. Vàrem fer una de les immersions de sempre. Aquesta vegada vàrem repetir la dels Cubs. Vam entrar a l''aigua l''Oliver (brutal) l''Alba, el Víctor (dos xavals Divemasters) un fent de guia (Víctor) i l''Alba de boia. Va venir també una noia (Marcela). Molt amable, bona companya. Destacar una més que acceptable visibilitat, així com la presència d''un bonic Cavallet de Mar que vàrem veure en acabar la immersió i entre un nus de corda enterrada a la sorra. L''orella dreta (barotrauma) va respondre perfectíssimament i no vaig notar cap molèstia. Perfecte i senzilla immersió per obrir temporada. Com sempre Vanas, impressionant! Contentíssim!', '2023-05-04 14:42:37', '2023-05-04 16:22:26');

-- Immersió 31
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 31, '2022-05-29', '11:58:00', '12:46:00', 24.2, 48, 200, 30, 170, 15, 'bona', 16.15, 19, 7, 'Col·lectiva CIB! Immersió de vaixell! Feia temps que no en feia una d''aquestes. Bé. Immersió bonica. No espectacular (visibilitat i fredor típica de primavera) però preciosa. i tant! La sortida no va començar massa bé!, pujant des de Barcelona amb la Sílvia i l''Iu (nano), l''altra noia (Paula va ser baixa última hora per covid), va ser impossible poder-los recollir en el punt acordat, ja que s''estava corrent una cursa enmig de l''Eixample i tots els carrers estaven tallats! Finalment, la Sílvia i l''Iu van poder baixar al passeig de gràcia des d''on vàrem poder arrancar cap amunt... La immersió inicialment va ser una mica agobiant i complicada degut a la mica de corrent que hi havia a superfície i em va ser dificultós anar de popa a prop de la tritonera!! brutal, estic fatal! sort de la corda lateral que hi havia a l''embarcació per anar fins al cap per on vàrem baixar. Malament. Després de cansament i una mica de caos entre bussejadors per baixar pel cap, vaig fer-ho altra vegada massa ràpid, i l''oïda esquerra se''n va ressentir. Fatal!, altra vegada amb dolor i costant de compensar (sort que va ser l''altre orella i no la lesionada l''any passat). Passat un dia, no sembla tant greu com la perforació de l''any passat, però malament, amb dolor, l''he apretat massa. ostia!!! Tot hi així, passats aquests primers 10min una mica agobiants, una vegada a -8m, vàrem començar a fer voltes per l''Ullastre II !!! Impressionant!!! paret vertical preciosa i plena de gorgònies!! increïble! (veure fotos a galeria). Vàrem anar molt bé un grupet de cuatre. L''Àlvaro (un crack) al capdevant fent de guia, l''Àlex, la Sílvia i jo. Després de donar voltes i inclús veure altres companys més experts del CIB (Jordi Clua, Josep), vàrem fer la parada de seguretat a -5m a el cap, per poder sortir molt millor i fàcilment cap a la tritonera. Màquíssima immersió!!! però em cal millorar molt encara amb tota la logística de vaixell.', '2023-05-04 15:21:56', '2023-05-30 10:50:46');

-- Immersió 32
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 32, '2022-06-19', '12:37:00', '13:20:00', 22.3, 43, 200, 50, 150, 12, 'bona', 17, 25, 8, 'Immersió per lliure amb la Sílvia (companya CIB). Vàrem pujar sols i després de dubtar entre anar a Tossa o a Blanes, per logística vàrem pensar millor a Blanes (pujàvem de Barcelona). Espectacular! Vàrem tenir la sort de provar immersió de Vaixell amb el centre. Aquesta vegada, el centre va voler provar primera immersió lluny de la seva zona habitual i amb una nova embarcació!, una neumàtica (Zòdiac)! Brutal! Va ser un viatge llarguet (motor en rodatge) i ens va permetre gaudir de la línia costanera entre Blanes i Lloret!, preciós! En arribar al punt d''immersió (Els bullents) vàrem saltar d''esquena (neumàtica) i després de baixar pel cap de fondeig, vàrem passejar per les lloses planes dels bullents. Molta llagosta i nudibranquis. Preciosa immersió amb la guia (parella de l''hilai de Blanes-sub, la Neus) i junt amb tres nanos dos d''ells de Granollers. Macos. En acabar va ser curiós perque en NO trobar la neumàtica, la Neus va tirar la boia d''ascens i vàrem procedir a l''ascens fent parada de seguretat sense agafar-nos a cap corda. La part negativa de la immersió va ser que al cap de 2 hores de finalitzar la immersió vaig començar a patir un dolor fort d''oïdes que em va donar tota la tarda fins que després de prendre un Ibuprofèn em va passar. Cal revisar què em passa perquè estresso massa les oïdes i no pot ser, ja que ho passo malament, molt malament en acabar la immersió. Malgrat tot, fantàstica immersió amb Blanes Sub! probablement un dels centres que avui per avui més m''agrada!', '2023-05-04 15:30:12', '2023-05-04 16:23:19');

-- Immersió 33
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 33, '2022-07-22', '16:28:00', '17:33:00', 21.0, 65, 200, 40, 160, 12, 'bona', 18, 29, 8, 'Immersió amb el CIB, amb nous companys (Ricard, Iris y Gemma). Vàrem ser només 4! l''únic instructor que va venir va ser en Toni Arcas! (per fi! un dels instructors dels del curs d''Open!). Vaig estrenar nova modalitat horari CIB: immersió de tarda! 15:30! Va ser una bona immersió a Mar Menuda. Vaig estrenar el nou neopré simple del Decathlon!! el de cremallera davantera. Un humit força còmode i varat. Malgrat notar un canvi en la flotabilitat, vaig poder adaptar-me bastant bé a la flotabilitat i vaig anar força còmode. Va ser una immersió bastant llargueta. Vàrem veure un llamàntol!!! brutal!!! Em va sorprendre la temperatura de l''aigua (primers 10m molt calenta! aprox 26ºC !!!) per desrpés en termoclina pronunciada, baixar a 17-18ºC a els 20m. Molt bonica immersió amb el CIB, Toni un Crack.', '2023-05-04 15:32:14', '2023-05-04 15:32:14');

-- Immersió 34
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 34, '2022-07-29', '11:01:00', '11:55:00', 21.8, 54, 200, 50, 150, 12, 'bona', 23, 29, 8, 'Després de l''última immersió amb els nous companys del CIB, vaig intentar animar a els nanos per una immersió lliure. Finalment, només li va anar bé a la Iris. Per logística, vàrem decidir de nou fer la immersió a Tossa amb Tossa Divers (centre cómode i amable). Malauradament vaig acabar fent-la sol!!! La pobre Iris no li va arrancar el cotxe i com que jo estava a Sant Pol de Mar, no vàrem poder marxar plegats. Total, que vaig fer la immersió només amb l''amo de Tossa Divers!! En Miquel!!! que resulta que xerrant amb ell, va treballar amb l''Oliver del Vanas dive!!! de la mateixa Quinta! 73! Sols, vàrem fer una molt maca immersió veient una gegant mola de sards a l''aquari! brutal!! brutal!! En Miquel un auténtic crack. Molt bon bussejador!! super tranquil, lent, molt bé! un crack (com l''Oliver...). De nou, Mar Menuda et garanteix immersió fàcil, còmode i et garanteix vida a el fons marí. Preciós.', '2023-05-04 15:34:48', '2023-05-04 15:34:48');

-- Immersió 35
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 35, '2022-08-21', '16:19:00', '17:25:00', 19.3, 66, 200, 40, 160, 12, 'bona', 23, 30, 7, 'Col·lectiva CIB (Toni + Roser). Bona immersió, llarga i amb bona visibilitat. Aquesta vegada força gent del CIB (però malauradament no coneixia a ningú...). Toni va formar grups amb parelles. Vaig anar en el grup del Toni i em va tocar com a parella un tal Boris (bon tio, molt bé). La guia de la Mar Menuda amb en Toni (o Roser) és una garantia d''immersió llarga i maca, ja que es coneixen molt bé els distints recorreguts que s''hi poden fer. Aquesta vegada, en Toni ens va fer el que s''anomena el recorregut de tot el "croissant" de l''illa. La vàrem recórrer i a més a més vàrem entrar en una petita cova (no hi havia estat mai!!!, maquíssima!!!). Aquesta vegada, molt satisfet de com vaig gestionar el vestir-me (posada de jacket), així com a l''entrada a l''aigua i el començament de l''immersió. Molt content també de rebaixar un quilet i sortir amb 7kg de llast i força còmode. Una vegada més moooooolt satisfet de molt bona compensació i sense generar estrés a les oïdes!!. Vàrem veure el de sempre a Tossa (Moles de Sards, Salpes, morenes i neros!). Als últims 5min d''immersió es va fer "fosc" degut a una tempesta. Vàrem acabar l''immersió amb una mica de pluja. Una passada, de nou, disfrutant altre vegada.', '2023-05-04 15:36:32', '2023-05-04 15:36:32');

-- Immersió 36
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 36, '2022-08-25', '10:30:00', '11:20:00', 15.0, 50, 200, 60, 140, 12, 'bona', 24, 30, 7, 'Immersió en solitari. Escapada a Blanes (entre setmana per vacances a Sant Pol), Immersió un pèl desorganitzada en l''organització a l''entrada a l''aigua (típic, temporada alta, força gent). Després de parlar amb el personal, em va tocar amb un instructor jove anomenat Manel. Discret però bon bussejador. Vàrem ser 5 més l''instructor (Manel), em va tocar amb un company que va tenir certs problemes de compensació a l''inici de la immersió, però que va poder resoldre. Va ser una bona immersió a ''La Seca''. Molt bonica, vàrem tenir tots un bon consum i vàrem rodejar ''La Seca''. Hi havia força vida i vàrem arribar a entrar a una petita cavitat, escletxa. L''anada cap a la seca va ser més interessant que la tornada. Vaig gaudir molt de la immersió i em vaig trobar molt bé. Bona immersió. Bona nova estona a l''aigua per seguir practicant flotabilitat i domini aquàtic. El més interessant (hehehe) va ser que per ser una immersió guiada, només em va costar 18€. Bons preus a Blanes Sub!! (gran dídac i hilai). La nota també positiva és que tot i sent Agost, vaig trobar aparcament just darrera al centre! quina sort!', '2023-05-04 15:39:52', '2023-05-04 16:23:41');

-- Immersió 37
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 37, '2022-08-27', '12:15:00', '13:11:00', 19.5, 56, 200, 100, 100, 12, 'bona', 24, 30, 7, 'Immersió en solitari. Havia quedat amb l''Iris. Ella venia amb uns companys de feina i amigues. Al ser molts, en Miquel de Tossa Divers em va dir si em feia res canviar de grup amb uns altres que en formaven grup de 4. Amb mi, vàrem ser 5, lògicament no em va importar passar de grup per anivellar grup de bussejadors per grup. La immersió va ser brutal. Molt molt xula. Molta visibilitat i bon consum. La nota bonica va ser que em vaig retrobar per casualitat amb en ''Lander'' !!, instructor que vaig conèixer en les primeríssimes immersions després de l''Open (vegeu aquest diari, immersió amb Edu i Maria). Molt content de la immersió vàrem veure un Dèntol gegant, llagostes i vaqueta suïssa (nudibranqui). Molt molt satisfet de com em vaig sentir a l''Aigua. En Lander una passada, brutal brutal brutal, com a persona, com a bussejador. Molt bon instructor (altra vegada em va agradar molt i li vaig dir). Ell em va comentar també que es notava que havia bussejat una mica més que l''última vegada!. Després comentant amb la Iris la jugada, molt bé. Va ser un dia bonic. Malgrat suar una mica per tornar al cotxe (estacionat molt lluny!!) vaig estalviar-me el que costa més de la immersió. El parking!!!', '2023-05-04 15:44:00', '2023-05-04 15:44:00');

-- Immersió 38
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 38, '2022-09-10', '16:46:00', '17:50:00', 21.2, 64, 200, 40, 160, 12, 'bona', 23, 28, 7, 'Tornem-hi. Col·lectiva CIB a Tossa! Com és habitual, amb en Toni i la Roser. Com sempre, molt bé. Aquesta vegada també vàrem ser grup important. Gran. Vaig tenir la sort de retrobar-me amb en Ricard (nano jove, soci que mini grup telegram amb Iris i Gemma). En Toni com sempre ens va agrupar per parelles. Vaig anar amb en Ricard. La Immersió xulíssima, llarguíssima, com sempre per Tossa. Vàrem fer la banyeta més curta del "Croissant". De vida, com sempre a Tossa, molta. Espectacular però els Dèntols enormes que passen per la punta de la baña. Al final de la banyeta, a uns 21m de profunditat hi ha una serie de forats, de recons que normalment sempre hi ha bròtoles, Meros, Llagostes. En Toni va comentar que ho coneix, i per això ens deixa (com a nens del cole!! hehehe) una estona en aquella zona, per tal de poder entretenir-nos mirant entre forats fent ús de les llanternes. Altra vegada, part negativa, pàrking.', '2023-05-04 15:48:59', '2023-05-04 15:48:59');

-- Immersió 39
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 39, '2022-09-18', '12:08:00', '12:39:00', 5.5, 31, 200, 150, 50, 12, 'bona', 22, 25, 7, 'Divertidíssim bateig col·lectiu i familiar!! Malgrat els del centre NO es van estirar gents, va ser en general correcte. Vàrem passejar donant voltes pels primers metres de la platja port pelegrí (la de davant del centre de busseig). Els bussejadors vàrem ser: Cristina, Enric, Quirze, Aran, Francesc, Jan, Pere, Gibert. Ho vàren fer espectacular. Molt bé!!!, de debò.', '2023-05-04 15:53:57', '2023-05-04 15:53:57');

-- Immersió 40
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 40, '2022-10-02', '10:59:00', '11:45:00', 6.4, 46, 200, 140, 60, 12, 'bona', 20, 25, 7, 'Tercer Bateig de l''amic Jordi Balasch! Fantàstic! com sempre! Cap de setmana genial a l''Ametlla de Mar amb la família Balasch (Arantxa, Jordi, Mercé i Xavi). Aquesta vegada vàrem passar el cap de setmana a l''Hotel Ametlla de Mar. Brutal. Bufet lliure, piscina, Spa, Terrasseta... fantàstic! Immillorable. Vàrem riure i passar-ho molt bé com cada any! El Bateig amb en Balasch aquesta vegada va ser acompanyant també a una parella on la noia s''estrenava amb el bateig junt amb un company expert. El bateig va ser una mica accidentat al principi amb la noia perqué no acabava d''entrar i sentir-se prou bé, però després de que ho arreclés l''instructora de plàncton diving (Aurora), va acabar molt bé. No va ser el millor bateig d''en Balasch perqué va tenir certs problemes amb la màscara (li entrava aigua) i perqué inicialmente va haber d''esperar a sota aigua força estona a que la noia que ens acompanyava a el bateig es tranquilitzés. Malgrat tot, va anar prou bé i ho tornarem a probar (si el destí ho vol) l''any vinent. Preciós!!! gràcies Jordi!!', '2023-05-04 16:08:18', '2023-05-04 16:08:18');

-- Immersió 41
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 41, '2022-10-02', '12:30:00', '13:20:00', 6.3, 50, 200, 140, 60, 12, 'bona', 20, 25, 7, 'Impressionant immersió successiva. Pràcticament mullat encara i corrents després del bateig, em vaig apuntar amb un grup familiar per entrar a l''aigua altra vegada. Aquesta vegada va ser al costat de la platja de Sant Jordi, a una cala anomenada Cala Vidre. Espectacular!! malgrat ser una immersió senzilla va ser brutal!! de les millors de la temporada!! em vaig sentir molt i molt bé. Vaig trobar-me amb una flotabilitat boníssima, molt còmode i practicant el busseig d''esquena. Vàrem passar per un prat molt bonic de posidònia. La visibilitat era espectacular degut a la poca fondària i vàrem passar per un arc/coveta molt xula amb uns contràsts de llum a l''entrada i sortida preciosos. L''instructor Manel, local, d''Amposta, molt ben parit i tot el grup molt familiar i simpatiquíssims. Em vaig sentir molt a gust. Molt bona experiència una any més al bussejar a l''Ametlla de mar! Vull repetir cada any!!!', '2023-05-04 16:10:23', '2023-05-04 16:10:23');

-- Immersió 42
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 42, '2022-10-16', '09:25:00', '10:19:00', 21.1, 54, 200, 40, 160, 12, 'bona', 21, 25, 7, 'Escapada solet cap a Tossa, amb Tossa Divers (Miquel), ja conec alguns instructors (Alex, Lander, Oscar...). Aprofitant cap de setmana anticiclònic, m''he trobat amb bon temps i encara bona temperatura de l''aigua. En Miquel em va dir que de les dues immersions guiades que fan (9h i 11h) millor anés a la de les 9h. Menys gent i millor mar. Dia de clàssic Madrid-Barça, bona trobada amb pares del Mireia (per la tarda), l''escapada matinera a Tossa a valgut molt la pena. He disfrutat de nou molt!! Comodíssima immersió amb bon company d''immersió (Àngel) i amb molt bon instructor Oscar! Hem recorregut TOTA la illa donant-li la volta i sortint desde la Banyera de Ses Dones. Força aleteig però bona immersió! hem vist de tot!! pops, una nàctra petita, una llagosta, un nero, un IMPRESSIONANT! banc/mola de Salpes amb un espet! i alguns nudibrànquis (vaqueta suissa), evidentment també algunes morenes. Disfrutant de nou de la confiànça del club, comoditat i bona immersió per recordar!! Aguantant encara amb l''humit del decathlon i sense guants. Gents de fred. Molt bé!!', '2023-05-04 16:14:37', '2023-05-04 16:14:37');

-- Immersió 43
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 43, '2022-10-19', '10:51:00', '11:36:00', 8.8, 45, 100, 110, -10, 12, 'dolenta', 22, 21, 7, 'Escapadeta entre setmana (dimecres) demanant dia de festa al curro. Immersió evitable. Un merda de visibilitat. No obstant, part positiva és poder realitzar també immersions d''aquest tipus per posar-se a prova i recordar que NO sempre la visibilitat ha de ser bona o molt bona. No és la realitat! He disfrutat però bastant. El grup erem, Senda (guia, gallec, ja conegut en anteriors immersions), l''Alba com a guia (boia), també coneguda en d''altres immersions, i un noi argentí que feia un refresc després de 3 anys. Tot bé, teniem que fer la immersió de les plataformes, però per obres al final hem hagut de modificar-la i anar a la també coneguda immersió dels cubs. Tot i la pèssima visibilitat hem anat aguantant i després de fer un recorregut pel costat de l''escull cap a la profunditat màxima de la immersió (aprox 10m) hem vist un pop molt bonic entre dos cubs. També molts super mini nudibranquis agafats en una mateixa alga. Estrelles vermelles també n''he vist unes cuantes, i avui per sort he pogut provar (el dia perfecte!!!) l''ús de la llinterna que m''ha anat molt bé per il·luminar els caus i el pop!!! Olvier, Senda, Alba.. Vanas!! genial com sempre!!!', '2023-05-04 16:27:01', '2023-05-04 16:27:01');

-- Immersió 44
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 44, '2022-10-22', '11:15:00', '12:17:00', 21.4, 62, 200, 70, 130, 12, 'bona', 19, 21, 7, 'Col·lectiva CIB. Brutal. Inicialment havíem de fer la immersió a la Caleta (Cala Morro del Vedell), però finalment va haver-hi canvi de plans degut a que bufava de Sud, i per tant, per orientació a la Caleta (Palamós) hagués estat el mar mogut i la visibilitat dolenta. Efectivament quan vaig arribar a Palamós, vàrem veure la caleta amb el mar molt mogut. Despreś de concentrar-nos i comentar amb en Toni Arcas, Roser, Jordi Regàs (tenien curs Open), vàrem decidir (ja estava mig acordat desde Barcelona), agafar les ampolles al centre H2O, però marxar a bussejar cap a Cala Sa Tuna. Així ho vàrem fer. Va ser guapíssim. Immersió rollo lliure, arribar canviar-nos al cotxe i baixar carregats cap a l''aigua. Brutal. Caleta acollonant. Poca gent, molt tranquils. Vaig coincidir amb en Ricard (nano platja d''aro) i amb la Gemma. Va ser acollonant. Preciós. Sens dubte, és la millor manera de bussejar. Amb gent que en sap i per lliure. És magnífic!! La part negativa va ser que em va costar compensar la oïda dreta i malgrat poder fer la immersió, en acabar i dinant a Palamós amb la gent del CIB vaig notar com en d''altres vegades, força malestar a l''orella i fins i tot en arribar a Barcelona vaig haver de prendre un Ibuprofè. Malgrant anar en compte. Malament!! vaig tornar a estressar massa les oïdes!! no pot ser!! Cal millorar.', '2023-05-04 16:30:41', '2023-05-04 16:30:41');

-- Immersió 45
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 45, '2022-11-13', '12:20:00', '13:17:00', 22.1, 57, 200, 60, 140, 12, 'bona', 18.17, 19, 9, 'Repetida i improvisada col·lectiva amb CIB. Toni i Roser. Brutal. Altre vegada cap a Sa Tuna!! Magnífic. Aquesta vegada, a més a més, va ser millor perqué ho vàrem planificar amb en Ricard (nano del CIB platja d''aro) i amb en Chema, veterà bussejador. Bona gent. com sempre. La cosa va anar de fàbula, ens va fer bon dia, una mica de boira a primera hora, però de nou, immersió lliure agafant ampolles i entrant sense pressa, sense centre, res... tranquilament amb en Toni i la Roser que són brutals, va ser fantàstic. Aquesta vegada, malgrat cosar-me bastant compensar inicialment, després No em va fer tant de mal l''orella com la vegada anterior. Em va fer molèstia però res a veure i sense necessitat d''Ibuprofeno. Sobre la immersió, vaig anar amb 9kg!! ja que vaig posar-me el fisterra i els pantalons curts amb butxaques. Malgrat tot, no vaig passar fred però tampoc em vaig notar sobrat, estava al limit, potser per la merda del mig-dolor orella dreta. Tot hi així, impresionant immersió veient nudibranqui gros groc maco, una Ratjada tipus Musaic brutal!! així com un esclop entre roques. La llinterna d''en jordi Rovisub, fantàstica. Una vegada més em va anar de fabula. Molt bona immersió!!! disfrutant altre vegada!!! ara si que potser, aquesta haurà estat la darrera de la temporada 2022!!!  🙁 sniff sniff!!!', '2023-05-04 16:32:11', '2023-05-04 16:32:11');

-- Immersió 46
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 46, '2023-05-07', '11:05:00', '12:01:00', 16.3, 56, 200, 40, 160, 12, 'bona', 17.15, 21, 7, 'Primera immersió temporada 2023!!!!! 👌✌🤩. Molt bé, varem pujar cap a Blanes el "sopita!!" (César, grup música Boca de Reg) i jo. Sols! vàrem llogar un parell d''ampolles de 12L. Ens va atendre molt bé l''Hilai (Com sempre) i vàrem entar a l''aigua, tranquils, super bé. Varem reseguir l''escull fins a la formiga enfonsada. D''allà vàrem tirar cap a "la seca", la vàrem bordejar una mica i vàrem tornar. Molt bé la immersió malgrat curiós, però en un moment donat que semblabem perduts entre la seca i l''escull, a el Cèsar se li va desenganxar l''ampolla, estàvem una mica desorientats i em va entrar durant uns 5min un agobiament prou important per tenir un desig fort de pujar cap a dalt! ostia, no em va molar, però després em vaig calmar, vaig respirar profundament, buscant referències a la roca, i ja tornant i ben orientats vàrem veure un espectacular pop! i se''m va passar tot ,vaig tornar super bé i disfrutant! Molt satisfet!!! bona estrena!!! espero forces amb el César! molt bé!! 👏', '2023-05-07 16:03:30', '2023-05-25 10:16:27');

-- Immersió 47
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 47, '2023-06-04', '11:28:00', '12:20:00', 27.2, 52, 200, 70, 130, 15, 'moderada', 18.14, 24, 7, 'Primera Col·lectiva CIB 2023!! Com a instructors del CIB va venir només en Jordi Regàs. Vaig coincidir amb l''Iris! va ser molt xulo. Vàrem estrenar CIB amb el César!! Impressionant Immersió. Igual que la de l''any passat però aquesta vegada va anar TOT molt i molt bé. Zero mal a l''oïda... baixant super tranquil i bé per el cap de la tritornera. Mar amb calma hi va ajudar moltíssim. Brutal, gents ni mica de mal a l''oïda i compençant molt bé. Em vaig sentir súper segur, fins el punt de que vaig baixar sense cap problema i sentint-me molt bé fins els poc més de 27m!!! Molta molta gorgònia gegant preciosa i parets verticals en la banda nord de la roca. Preciosa immersió que vàrem acabar dinant al cou-cou de Calella amb la gent del CIB. Espectacular dia. En serio. Acollonant immersió malgrat típica visibilitat regular de primavera!! Fitoplàncton!!!', '2023-06-05 20:36:36', '2023-06-05 20:42:13');

-- Immersió 48
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 48, '2023-06-16', '11:35:00', '10:47:00', 21.1, 48, 190, 60, 130, 12, 'moderada', 21, 28, 7, 'Escapada solet a Mateua. Immersió Vaixell divendres matí poca gent tranquila, dos companys sense guia Ricard i Paula, el Carles de Mateua hem va dir que m''apuntés amb ells així evitava pagar guia. Super bé. Maquíssims. Immersió preciosa amb tres arcs guapíssims. Contrallums molt guapos! Les cambres per fora evitant túnel estret per Advanced. Brutal!! Zero dolor oïda, vaixell còmode. He xal•lat moltíssim!! 🤤😍', '2023-06-16 21:45:35', '2023-07-10 11:03:16');

-- Immersió 49
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 49, '2023-06-25', '11:07:00', '11:48:00', 19.4, 41, 200, 100, 100, 12, 'bona', 22.2, 30, 7, 'Guiada a Tossa amb l''Alex (instructor) de Tossa Divers. L''Alex un cachondo, super simpàtic (com sempre). El césar (sopita) i el seu fill Luca em vàren recollir a Sant Pol (Sorli) i vàrem pujar cap a dalt. Molt bé, vàrem ser un grup de 7. Tossa a petar, però aigua espectacular. Vàrem arrivar fins a coveta on al fons hi havía un congre gran. Llenterna perfecte!!! congre espectacular!! després en vaig veure un altre junt amb una morena i una llegosta preciosa. Immersió senzilla però molt xula. Visibilitat excel·lent. La llàstima és que al anar amb Opens que feien refresh i que feia temps que NO bussejaven, van consumir molt ràpid i va fer que la immersió fos força curta, així que a la tornada vàrem haver d''espavilar i no poder parar gaire per tal de que no se''ls acabés l''aire. Malgrat tot, vaig disfrutar una vegada més moltíssim!! Amb el sopita (clarament my favorite buddy!!!) i el seu fill, espectacular, com sempre... Per quan la propera!!!? 🤤😍', '2023-06-26 08:58:35', '2023-07-10 11:02:52');

-- Immersió 50
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 50, '2023-07-09', '11:42:00', '12:34:00', 17.9, 52, 200, 90, 110, 12, 'moderada', 21, 29, 7, 'Immersió número 50!! just davant del port de platja d''aro hi ha tres pics que conformen la Llosa de Platja d''aro... un d''ells és la Llosa de Garbí que és on vàrem anar. Immersió senzilla, no massa profunditat però va d''haver de ser així ja que ens va bufar molt de vent (llevant) i hi havía força mar de fons. Molta gent, en el "ballenato" tal com es diu l''embarcació i nosaltres amb el César vàrem anar amb el Siscu (amo del centre) amb una neumàtica petita. La immersió va estar bé, molt bé, però amb dificultats per entrar ja que hi havia molt d''onatge i la neumàtica petita es movia molt!!! Sort del César que em va tranquilitzar i ajudar a posar-me l''equip pesat. Grande César!!! 😍😍. Una vegada a l''aigua, una mica caótic perque mal planificat i sense massa rumb. Vàrem seguir a el grup i a els "guies". En el fons, inicialment vàrem passar per un espectacular arc, i deprés al fons força roca i posidònia. Molta vida. Em va agradar molt el lloc de l''immersió, pero desafortunadament no gaire l''organització probablement pel de sempre. A ple estiu... massa gent!!!! Una altres experiència és que en Siscu ens va fer treure el jacket desde l''aigua per recollir-lo i vaig pujar "amb un salt" a la zodiac directament i sense escala. Guapíssim. Quines ganes per la propera!! l''oïda per cert... com una campiona... un pelet inicialment pels nervis, però super super bé!!! https://opistobranquis.org/es/membres-punts-d-immersio/260', '2023-07-10 07:41:59', '2023-07-10 11:02:18');

-- Immersió 51
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 51, '2023-07-16', '12:20:00', '13:07:00', 27.6, 47, 200, 70, 130, 12, 'bona', 14.24, 32, 7, 'Col·lectiva amb el CIB. Amb en sopita (César) com sempre, , hi varem tornar! Ja havia parlat també amb en Ricard. Em trobo també amb la Gemma i en Chema!. En Jose (xaval jove i la seva parella que ja ens havien guiat a Sa Tuna) és el que ens guia. Torno a coincidir també amb l''Alemana. La immersió xula, NO espectacular però molt bé. Vàrem entrar a l''aigua per un dels extrems de la cala (després de passar per un cami amb les terrasses) i vàrem anar aletejant fins ben endins fins al costat d''una roca que sobresurt (la negra), allà vàrem baixar a uns -10m per seguir aletajant cap a mar obert i al cap de 5min. vàrem baixar fins a uns -25m on vàrem passejar per després tornar poc a poc. Bé, fons de poseidónia i visibilitat acceptable. Forces nudibranquis. Immersio baratíssima! 12€. Un pelet curta, però molt satisfet!', '2023-07-17 13:40:15', '2023-07-17 13:41:50');

-- Immersió 52
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 52, '2023-07-25', '16:30:00', '17:44:00', 21.6, 74, 200, 50, 150, 12, 'bona', 26.25, 28, 7, 'Col·lectiva CIB. No falla. Finals Juliol amb Toni i Roser. Com sempre, espectaculars! Tossa, sempre. Entre setmana, dimarts i a la tarda (15:30). Aquesta vegada, ni el César ni el Ricard vàren poder acompanyar-me. Vaig anar-hi igualment. Roser va anar amb un parell a els Perduts (molt més enllà de l''illa, sembla que s''ha d''aletejar moltíssim). Amb Toni ens vàrem quedar per el croissant, recorrent el de sempre, preciós com sempre!! Vàrem veure bròtoles, un pop, moltíssimes morenes, una llegosta, moles com sempre de sards estàtics! Al tornar, n''hi havia dos que es varen quedar amb poc aire, el Toni em va dir junt amb uns altres que anés amb la Roser que la vàrem trobar també a la tornada, vàrem donar més volteta en una escletxa molt xula que va mostrar Roser, immersió com sempre amb aquest parell llarga i barata!! brutal!! ja no se''n fan d''aquestes. Com va dir en Toni... aixó és una mica com un "dos por uno!!". Espectacular. Super satisfet!', '2023-07-26 16:33:19', '2023-07-26 16:33:19');

-- Immersió 53
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 53, '2023-07-29', '11:19:00', '12:19:00', 21.5, 60, 200, 50, 150, 12, 'moderada', 24.14, 30, 7, 'Col.lectiva CIB amb parella Jose i Joana. Vàrem pujar amb en César, com sempre. Espectacular . Immersió inicial guapíssima! S''entra fent un salt de gegant desde les roques. Per arribar a aquestes, així sí, una mica rollo caminar tot equipat... (especialment quan fot una xufla insoportable!! 😪). Una vegada a l''aigua, la primera zona, espectacular, bona visibilitat i comença amb un túnel ample, preciós, fàcil... guapíssim! 😍 En sortir del túnel i començant el passeig... almenys, aquesta vegada, merda... la visibilitat cau en picat... i sorpresa! brutal! termoclina duríssima a -12m passant de 24 graus a 15!!!!  el Jose havía portat un shorty i ho va passar fatal! impressionant caiguda de temperatura. A partir d''aquí, immersió fluixa i amb poca visibilitat. Estrena doncs de "La Depu" bastant decepcionant... 😥, tot i això, amb una mica més de visibilitat ha de ser una molt maca immersió... fins la propera!!!', '2023-07-30 10:14:47', '2023-07-31 10:26:56');

-- Immersió 54
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 54, '2023-08-12', '09:16:00', '10:06:00', 18.3, 50, 195, 70, 125, 12, 'bona', 21, 29, 6, 'Immersió escapada Tossa amb el Sopita (César). Provem 8:30 al centre! Guiada senzilla, evitable. Molt senzilla, entrada per banyera i també sortida però petat de gent!!! 😱🫣, és clar, Tossa i 12 Agost! malgrat tot, molt còmode oïda dret principi una mica dolor, bloqueig, però després ok..., bastanta vida, aquari com sempre mola de sards preciosos i a la barra sards imperials gegants!! un pop petit, parell de llagostes un cavallet de mar localitzat! i al final sortint per la banyera i enmig de moooolts bussejadors, amagadeta una escòrpora. Una més cap al sac!! 💪💪🏼', '2023-08-12 12:04:17', '2023-08-12 16:01:13');

-- Immersió 55
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 55, '2023-08-15', '11:46:00', '12:37:00', 27.7, 51, 200, 70, 130, 12, 'bona', 14.21, 29, 6, 'Brutal. La millor immersió temporada 2023, i potser top 3 del total d''immersions. Primera immersió cap de creus!! és una altre lliga. Pista negra!!! acollonant regal 50 anys! tota la familia lloguer barcassa sant isidro i mentre familia bany cales port lligat, jo amb neumàtica immersió amb la Maria, amiga de Núria (Núria no podia molta feina...😪), Maria brutal, mano a mano sols per ses ielles! corall vermell, morenes, espets!! molt molt molt molt i mooooolt de peix! Amb la Núria ja em va dir que això no es res que puji setembre perque em portarà a llocs millors!! ostia!!? però si va ser brutal!? En fi, espectacular regal de la miki! la millor!!! ❤️❤️😍😍', '2023-08-16 08:11:35', '2023-08-16 08:11:35');

-- Immersió 56
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 56, '2023-08-26', '15:47:00', '17:03:00', 16.3, 76, 200, 60, 140, 15, 'dolenta', 26.22, 28, 7, 'Col•lectiva CIB. Per mal temps es va cambiar de Ullastre I a Morro del Vedell, 😪. Una merda d''immersió. Primer, perqué em va agafar agobio important (ganes de sortir immediatament) per mal oïda dret (normalment és el dret, el que es va perforar...) ó potser per sensació falta d''aire al aletejar durant uns minuts entre aigues (com a Blanes!!!) i a ritme altet (no massa, però mala forma!), també per la calor! (a poca fondària), en definitiva... mal rotllo! i el sopita es pensava que era conya!! 🫣😱😬, i segón, per mala visibilitat. Al insistir, en Toni va parar, vàrem estar en una roca veient un nero i això em va salvar, vaig poder tranquilitzar-me i continuar la immersió, ja molt millor, no al 100% bé, però controlant ja l''agobio. La termoclina va ser brutal però ja no tant de temp. sinó de visibilitat. A la que allunyàvem o baixavem a més de 14m, la visibilitat era horrible (2, 3 metres) fins el punt de que Toni va girar cua ajudànt-se amb dificultat de la brújula. Els lots van ser imprescindibles! En fi, immersió extranya i lletja però en alguns punts de visibilitat xula! com l''arquet que vàrem passar o els congres amagats als peus de la senyal de la rosa dels vents. Un altre experiència aprofitable!!', '2023-08-27 08:43:39', '2023-08-28 19:17:14');

-- Immersió 57
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 57, '2023-10-08', '10:05:00', '10:45:00', 5.6, 40, 200, 150, 50, 12, 'moderada', 24, 28, 7, 'Quart Bateig Balasch!! Excurció com cada any a l''Ametlla. En un principi NO teniem que fer immersió. Aquest any s''havia afluixat una mica per temes logístics futbol Jofre i Xavi, però al final vàrem decidir escapadeta diumenge matí ben dora. Immersió amb nou centre (Ametlla Diving), segons Balasch, millor que Plàncton. Desde el meu punt de vista, similar. Juanjo instructor i Paco. Teniem que fer bateig Balasch però com sortida petita amb altres bussejadors Open (com jo). Finalment vàrem anar només els tres. Inicialment, immersió caótica ja que Balasch no s''enfonsava i amb juanjo, vaig aguantar Balasch mentre ell es treia pastilla cinturó per afegir més llast a Balasch. En aquest punt, Balasch em va dir al sortir que es va sentir una mica agobiat. Jo després de la intervenció també!! altre vegada! amb calor!! vaig relexar i vaig aguantar bé. Seguint immersió, al final vàrem disfrutar malgrat visibilitat regular. Vàrem veure pop petit. Satisfets per probablement tornar-hi any vinent. Veurem!!! 👌😍', '2023-10-09 13:07:08', '2023-10-09 13:07:08');

-- Immersió 58
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 58, '2024-06-23', '09:58:00', '11:03:00', 9.8, 65, 200, 100, 100, 12, 'bona', 21, 20, 8, 'Primera immersió temporada 2024!! Senzilla però molt xula!! Finalment! després de pràcticament 3 anys l''Edu va tornar a fer una immersió! vàrem decidir que aprofitant que passariem de nou el Sant Joan amb tota la colla de l''Escola Mireia a Calella de Palafrugell (com altres anys) doncs que aprofitariem per fer una immersió de platja senzilla a Port Pelegrí! per lliure! sense instructor només l''Edu i jo vorejant desde la platja de port pelegrí cap a les roques de Sant Roc. Fons amb molt posidònia. Va ser una immersió tranquileta però molt gustosa!! Bon arranc de temporada sensacions perfectes!!!', '2024-06-27 13:00:29', '2024-06-29 21:11:38');

-- Immersió 59.1
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 59.1, '2024-07-24', '11:35:00', '12:20:00', 5.0, 45, 200, 100, 100, 10, 'bona', 26, 37, 7, 'Amb un "mono" de busseig ja prou important, i sense companys (sopita) ni CIB en disponibilitat (no soci aquest any!!!) doncs vaig anar desde Sant Pol a veure el Jordi de Rovisub al Poble nou de Pineda i parlant amb ell em vaig dir-li de llogar ampolla de 10L per veure escull Sant Pol a poca profunitat, però que la pega que anava sol... que teóricament no es pot, etc..., parlant amb ell em va convèncer (que gran el Jordi...) dient-me que si no feia tontaries i anava tranquil i segur que ell ha bussejat sol molte vegades. Comprenent els dos que efectivament una de les coses que més costa (me n''he adonat durant tot aquest temps... ) és la logística i la disponibilitat/dependència del busseig, el fet de poder no dependre de ningú, només de tú mateix, et permet entrar a l''aigua de manera molt més fàcil i ràpida. Dit i fet, ho vaig fer, i va ser fantàstic!!!! no em vaig trobar gents insegur i vaig bussajar sol durant 45min per el segon escull enfonsat i en paral·lel que hi ha a l''espigó de Sant Pol, sortint per l''entrada que hi ha entre l''espigó i el balconet de la punta. Brutal!! hi ha unes canonades antigues que em van servir per orientar-me i no perdrem, després, a més a més sense deixar mail les roques de l''escull enfonsat. Sí, només 5m però la sensació sota aigua brutal com sempre! a més a més sense cap pressa i molt econòmic! en aquestes va venir en Pere (germà) fent snorkel i em va localitzar, aleshores vaig sortir a superfícile, li vaig dir que tot ok, que seguia més estona que encara em quedaba mitja botella. I així és quan vaig fer la següent immersió (successiva) després d''entre 5 i 10 min. a superfície a l''aigua parlant amb en Pere.', '2024-08-12 12:26:02', '2024-08-15 16:50:40');

-- Immersió 59.2
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 59.2, '2024-07-24', '12:35:00', '13:25:00', 5.0, 50, 100, 45, 55, 10, 'bona', 26, 37, 7, 'Continuació immersió successiva. Una vegada, Pere (germanet) va controlar on estava, i parlant desde superfície aigua, vàrem acordar que seguir allà mateix un rato més i que no patís per res. Ok, així va ser, vaig tornar cap els -5m per estar casi una horeta més per gaudir dels neros i els sards en l''escull paral·lel enfonsat que hi ha just davant el balconet de la punta. La bonica antiga tuberia dona una forma i un senyal perfecte per no perdres i quedar-se en el triangle submarí que malgrat tenir poca profonditat (5m) permet veure bancs de salpes sards i neros entre els forats de les roques. Tots ells aixo sí, duna mida petita-mitjana. Vaig disfrutar moltíssim i vaig estar molt cómode i tranquil anant sol. Única part negativa. Logística. Molta calor!!! vaig entrar massa tard i el sol picaba molt fort a la sorra abans d''entrar, a més a més, l''aigua estava una mica picada i per les roques (costat balconet) va ser una mica difícil manegar el pes de la botella plena 10Kg. Una altre nota molt negativa va ser que en finalitzar l''immersió, durant la tarda em va fer molt mal les orelles i vaig haver de pendre un ibuprofé. Molt malament el pujar i baixar d''entre 0m i 5m!!! suficient per estressar i destrossar-me les oídes. molt malament això. Tot i així, m''ho vaig passar molt i molt bé!! 😍👌😍', '2024-08-12 13:36:54', '2024-08-15 16:49:11');

-- Immersió 60
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 60, '2024-08-09', '09:30:00', '10:15:00', 5.0, 45, 200, 1, 199, 4, 'excel·lent', 28, 36, 3, 'Joguina nova!!! Espectacular!!! 😍😍👏🎉🎉👌😍😍. Encadenant l''immersió anterior per lliure i quedant-me un mono molt important, vaig veure que el tema passava per poder aconseguir minimitzar moltíssim la logística d''entrada i sortida de l''aigua i en el punt de l''escull balconet de Sant Pol. Le meva mar menuda de casa!!! Navegant per internet i pensant, vaig decidir comprar (veure fotografíes i explicació en un article blog sóc Balena). En tot cas, impressionant la millora en la logística entrada a l''aigua. Aixecant-me dora pel matí, vaig anar al balconet com sempre, amb el carro de la compra i posant-hi a dins el back pack + ampolla alumini 4L. Impressionant. La sorpresa i l''apranentaja va venir quan entrant per primera vegada amb barret, neopré sense mániga i semarreta licra, només amb 3kg no baixava!!! inclús a 4.5m fent esforços, molts, per no pujar cap a dalt. Després de 10min i veient la incomoditat, vaig sortir i em vaig treure el barret, la samarreta i el neopré. Tot i quedant totalment despollat només amb el banyador i les ulleres, vaig millorar molt però seguia donant flotabilitat positiva. Vaig aprendre que l''alumini és completament diferent a l''acer!! pesa molt menys i a més  a més tenint en compte que l''ampolla és més petita! (4L), tot hi així vaig poder gaudir durant aprox. 48min flipant amb la visibilitat espectacular!! com mai!! una autèntica peixera!!! en Jordi de Rovisub un super-mega-crack!!! omplint l''ampolla per només 6€!!! i acceptant-ho!! no com el de freatic de castillejos que No em va acceptar omplir l''ampolla per no passar certificat CE. En tot cas, amb Rovisub Jordi com a solució va ser una merevella. Molt molt guapo!! ja estic boig, per tornar a portar-li l''ampolla d''aqui dos dies per reomplir i tornar a l''aigua, aquesta vegada sí, amb més pes per estar totalment cómoda!!! quina canya de logística!!! súper fàcil!!! per fi!!! satisfacció plena per només 6€ i ràpid!!! 😍😍👏👏👏', '2024-08-12 13:50:33', '2024-08-15 16:47:39');

-- Immersió 61
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 61, '2024-08-15', '13:15:00', '14:18:00', 4.7, 63, 200, 0, 200, 4, 'dolenta', 27, 26, 7, 'Tornant a omplir la joguina... aquesta vegada vaig triar la Platja del Morer. Dia del meu aniversari! 51 anys!!, el dia abans va estar plovent molt tota la tarda. Va refrescar molt, i en mig de la pluja vaig anar de nou cap a Rovisub a omplir ampolleta (6€), amb ampolla pleneta al cotxe vaig observar com de malament pintava ja que tota la tarda va refrescar molt (fred!!) i no parava de ploure. Bé, finalment ho va fer cap a les 23h de la nit. L''endemà anant cap a la platja del Morer amb tota la familia (Núria, nanos i cosins) vaig comprobar com per haver estat plovent, el dia s''havía aixecat i permetía anar a l''aigua. Desde fora la mar pintava espectacular, i el sol apretava. Quin canvi!! Malgrat això, al posar-me dins l''aigua vaig comprobar com la visibilitat era dolenta, no bona. Però bé per trobar sensacions i bussejar també amb visibilitat justa! (5m). Les lloses del Morer, molt justetes, pelades, tanmanteix, un petit canó va ser xulo de passar. De la immersió em vaig emportar una bona experiència comprobant que aquesta vegada portant 9Kg de llast va ser massa! fins al punt que aprofitant que en Gibert feia snorkel, vaig treure''m una pastilla de 2kg per donar-li i que la portés a la sorra. Oli en un llum!!! la configuració de 7kg amb camisa licra i res més és el llast perfecte (potser amb 6kg encara hagués estat millor) però amb 7kg molt bé per mantenir una flotabilitat còmode a 4m!!! 💪👌🙌👏. A nivell de fauna, un banc espectacular de salpes i la sorpresa de la immersioneta! quan anava despistat allunyat una mica de les lloses de cop i volta 3 espets davant dels morros creuant-me preciosos!!! impressionant les sorpreses que dona la mar. Fins la propera ben aviat!! a recarregar!!! 😊🤣', '2024-08-15 16:45:12', '2025-03-08 15:34:21');

-- Immersió 62
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 62, '2024-08-17', '09:55:00', '10:38:00', 5.0, 43, 200, 50, 150, 4, 'dolenta', 25.26, 26, 7, 'Perfecte. Logística facilissim. M''aixeco dora, entro màx. a les 10h... no hi ha ningú, i llast dominadíssim! Amb ampolleta 4L i sense barret ni neopré (nomes semarreta licra) el llast perfecte per flotabilitat neutra tirant a negativa són 7kg totals de pes! Immersió no masses bancs, poquets neros i visibilitat dolenteta perö suficient per gaudir sota aigua, reservant tota la reserva pels nanos i amb sorpresa final d''un popet ben bonic i recollit! ja penso de nou amb la recàrrega!!! 😍😍🙃❤️❤️', '2024-08-17 13:32:22', '2024-08-17 16:26:46');

-- Immersió 63
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 63, '2024-08-23', '16:02:00', '16:16:00', 4.8, 14, 50, 0, 50, 4, 'moderada', 27, 28, 7, 'Enregistrava la immersioneta o no? va ser un capbussó de només 14 minuts! És igual. Enregistrada! Tanmateix, la immersioneta amb només reserva, em va servir per conèixer a quin temps li correspón la reserva, de manera aproximada. Bé doncs, val a dir que en moviment tranquil i amb moments inmòbil, tot entre 2.5 i 4.5 metres, el temps van ser aquests 14 minuts. La immersioneta va ser prou bona per tornar a practicar logística entrada i sortida desde balconet. Per això, i perque posar el cap sota aigua encara que només siguin 14 minuts, m''enganxa, així va ser. Ganes de propera!!😍', '2024-08-24 16:25:12', '2024-08-24 16:35:17');

-- Immersió 64
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 64, '2024-08-24', '09:26:00', '10:22:00', 5.4, 56, 200, 3, 197, 4, 'bona', 26, 28, 7, 'Apa-li!! tornem-hi!! Cap a Rovisub, recàrrega 6€ i ampolleta preparada. En mig dels preparatius Havaneres Fira Mar, ben dora entro de nou al Balconet. Igual que la super-mini immersió anterior, aquesta vegada també amb la novetat de portar el back-pack només amb el plàstic! (vaig treure la funda d''espuma per millorar amb flotabilitat negativa). Molt bé, es va notar, ja que aquestes dues vegades, sense aquesta espumeta i posant-me a sota el neopré xaleco de 2.5mm + el barret prou gruixut, mantenint els 7 kg, no vaig tenir cap problema en baixar. Immersió amb bastanta bona visibilitat. Aquesta vegada amb poc Nero i pocs bancs de sards. Fent el mateix recorregut de sempre (Escull enfonsat i canonades antigues), vaig badar força estona, estirat, estàtic, veient a contra llum un conjunt de salpes prou grans. Precioses movent-se en grup lentament per l''escull. Impressionant. Super satisfet de nou de la immersió. Ara el Jordi (Rovisub) de vacances una setmanaeta, i a esperar-me a la tornada per mirar de fer potser la última recàrrega abans de tornar definitivament a Barcelona per començar a currar... 🙄😁', '2024-08-24 16:45:34', '2024-08-24 16:45:34');

-- Immersió 65.1
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 65.1, '2024-08-30', '13:40:00', '14:09:00', 4.9, 29, 200, 110, 90, 4, 'bona', 27, 30, 7, 'Immersioneta divendres 30 Agost, solets en Jofre i Jo. Sols, no podia deixar el nano amb ningú (estavem sols a Sant Pol), així que el nano em va acompanyar i vàrem anar a la platja de les Escaletes, amb la sort de poder tenir una mica de sorra per plantar Umbrella i poder sortir jo durant una estona mentre nano sol a la umbrella amb el mòbil (poca gent ja a Sant Pol). Espectacular, entrada fàcil còmode i agradable com sempre (Jofre em va fer un minivideo que he penjat a Abellot Photoprism). Sense veure res especial, vaig voler sortir molt abans per poder fer amb en Jofre prova de botella. El nano, ho va probar altre vegada i amb més estona, però tot i fer-ho molt bé, no l''entusiasme en absolut. Amb això doncs, vaig decir consumir tota l''ampolla tornant a fer immersioneta (65.2) amb més estona i gaudint allà mateix i a només 3.5m d''un parell de pops.', '2024-09-02 20:39:40', '2024-09-02 20:39:40');

-- Immersió 65.2
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 65.2, '2024-08-30', '14:15:00', '14:47:00', 3.5, 32, 110, 0, 110, 4, 'bona', 27, 30, 5, 'Immersioneta successiva. Tenint en Jofre jugant per el trencall, vaig tornar a entrar per observar en la zona del Balconet just a sota del balcó (roques) un parell de pops. A més a més, la immersioneta em va servir per jugar i provar de posar-me només 4 kg de llast cinturó (x2 pastilles de 2kg) que més amb el kg del back pack, sumàven un total de 5kg. Bé, no incòmode, però si patint una mica especialment quan l''ampolla estava pràcticament buida. Vaig estar jugant molt en treure''m el backpack i respirar només aguantant l''ampolla amb les mans. També en esgoar completament tot l''aire i comprobar com gradualment és angoixant com vas notant que et quedes sense aire i com has de xuclar fort les últimes 10 pipades per obtenir aire. Quina por! quina agonia!! Altra vegada jugant, exprimentant a sac i disfrutant com un boig de posar el capet sotaigua! Quedarà encara alguna altre recàrrega possible en els propers caps de setmana complicadíssims de Setembre!? veurem!!! 😩🤷‍♂️🙏🙏', '2024-09-02 20:48:15', '2024-09-02 20:48:15');

-- Immersió 66
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 66, '2025-05-25', '12:00:00', '12:45:00', 8.5, 45, 200, 100, 100, 10, 'bona', 19, 25, 8, 'Cinquè bateig Balasch! 🙌👏, molt xulo amb la Lídia (ajudant temporada blanes-sub) molt simpàtica. Amb en balasch vàrem estar super cómodes. vam anar els tres molt bé, tranquilets, a en Balasch li va costar una mica compensar inicialment, però desrpés ok. va anar molt bé, bastant bé solet... vàrem estar força estona, vàrem arribar fins esplanadeta, va estar força bé perque vàrem estar estoneta. Visibilitat bastant bona, malgrat una mica menys en certes zones. Blanes peladet, però vàrem veure un pop petit maco. Preciós dia, moltíssimes bones sensacions i estrena temporada 2025!!!!', '2025-06-02 15:45:30', '2025-06-02 15:46:15');

-- Immersió 67
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 67, '2025-05-31', '10:58:00', '11:55:00', 7.4, 53, 200, 100, 100, 12, 'dolenta', 19, 26, 7, 'Després de l''últim bateig amb en Balasch, em vaig quedar amb moltes ganes de tornar a l''aigua (és clar, va ser un inici de temporada plàcid i molt agredable!), això va fer que contactés entre setmana amb Oliver de Vanas Dive de Barcelona per fer una sortida, ràpid i fàcil desde Barcelona, dissabte matí. Dit i fet. Tot va anar perfecte ja que Oliver increible com sempre i la gent, nanos que va contractant i els grups que es monten per les sortides son molt macos. Desafortunadament la realitat és que a Barcelona i per aquesta època (Maig, Juny) és bastant merdós. Així és, la immersió una merdeta perque visibilitat bastant dolenta (no més de 3m), fins el punt de que els primers 10min no vaig estar gaire cómode i vàren tornar una mica els fantasmes del passat trobant-me una mica agobiat 😬😥. Tot i així, després d''anar-me relaxant, malgrat tenir una visibilitat dolenta durant tota la immersió, vaig tractar de focalitzar-me amb vida, roca i quelcom més proper, respirant relaxadament i així vaig aconseguir aguantar bé durant tota la immersió. Vàrem arribar fins les plataformes (com sempre xules per estar a sota...) però el anar i el tornar un aborriment d''immersió, poca vida, mala visibilitat, un rollo!!! però una vegada més amb les bones sensacions i disfrutant d''estar una estona sota  aigua!!! A per la propera!!! (però NO a Barcelona... hehehehe 😋).', '2025-06-02 16:10:33', '2025-06-02 16:12:10');

-- Immersió 68
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 68, '2025-06-14', '12:19:00', '13:03:00', 5.3, 44, 190, 5, 185, 4, 'bona', 23, 29, 7, 'Primera immersió amb ampolleta 4L de la temporada! Molt bé!! Pujo sól cap a Rovisub ja que había quedat amb en Jordi per recollida de botella després de que li passés el manteniment anual i la carragués. Brutal el Jordi com sempre!! (25€ tot! espectacular...). Una vegada recollida ampolla, vaig decidir anar cap a Blanes per probar nova logística fàcil de deixar cotxe a zona blava, i carregar botella desde parking zona blava fins l''escull. Ostia! perfecte!! i és clar... res a veure el fons de Blanes amb el de Sant Pol... ràpidament agafes profunditat i gaudeixes a sac de petits canons i roques. Gran racó per anar amb l''ampolleta!!! Uau!! repetiré segur!! increible primera immersió facilíssima de logística. Una vegada més vaig disfrutar moltíssim! Ara tot apunt per repetir el mateix però a Calella de Palafrugell i per Sant Joan!! ja no depenc de si Edu vol o no vol bussejar... no depenc de ningú!!! 👏🙆‍️☺💪🎉', '2025-06-14 13:52:45', '2025-06-14 23:08:17');

-- Immersió 69
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 69, '2025-06-19', '18:30:00', '19:01:00', 3.5, 31, 140, 0, 140, 4, 'bona', 24, 26, 7, 'Dijous! entre setmana, teletreball Sant Pol i després del curro (18h) bàrtols i cap a l''aigua! Immersionets senzillíssima. Entrant pel balconet aquest any de moment amb sorra fàcil. Buscant lateral espigó i canyería antiga. Visibilitat bona, però en funció de la direcció es tornaba més dolenta. Ostres, disfrutant molt altre vegada inclús amb quelcom tant senzill. Increíble banc de salpes petites rodejant-me per tot arreu. Contra llums maquíssims. Tornat i remanant per l''antiga canyeria, sota la mateixa un Nero!! aquesta vegada era petit però tirant a mitjà. Guapíssim! La part negativa de la immersió és el temps. Com que vaig omplir l''ampolla desde Badal Sub i transferint aire d''una de 12L plena cap a la de 4L. Vaig observar que la de 12L queda amb 150bar i aproximadament igual que la de 4L. A partir d''aquí, el tio de Badal sub NO va saber com acabar d''omplir-la. La part positiva és saber que l''ampolleta de 4L a 140-150 bar, dona per màx. 30min. poca cosa. D''altra banda, em va servir per detectar que per el mini-baròmetre de l''ampolla veia que perdía aire!!! 😬😢. Caldrà revisar/comentar amb en Jordi de Rovisub! A nivell de temperatura, espectacular. zero fred. Gaudint molt de nou!! i veient que serà el pa de cada dia en quan estigui a Sant Pol aquest estiu. Miraré però de fer aquestes immersionetes a primera hora del matí (cap a les 8h!!) que és quan l''aigua acostuma a estar impressionant! Bona!', '2025-06-19 20:50:38', '2025-06-26 09:00:25');

-- Immersió 70
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 70, '2025-06-23', '08:49:00', '09:21:00', 5.8, 32, 140, 3, 137, 4, 'bona', 21, 28, 7, 'Preciosa Immersió. Sol! Escapada impressionant com cada any amb la penya Mireia cap a Calella de Palafrugell (Camping). Aquest any Edu no va voler bussejar, i per NO deixar escapar oportunitat vaig planificar immersineta per lliure amb ampolleta!!! perfecte!! en Marc Satorras em va acompañar amb una mica d''snorkel i quedant-se a la sorra llegint el diari. Impressionant, vaig veure ràpid una bestina, rajada, també disfrutant de molta posidònia i mini canons per la platja. És impressionant bussejar així per les caletes de Calella!!! haig d''aprofitar-ho sempre que pugi!!! és impressionant. Molt bé, contentíssim d''aprofitar l''ampollta malgrat amb Badal-Sub de moment només em poden omplir la meitat. Haig de comentar que el jordi de Rovisub l''ompla tota!!! però almenys, sí que és veritat que logísticament com a mínim, ja sé d''un lloca a Barna on me l''ompliràn algo!! Bravo!! 🙏👏👌. En definitiva, gaudint altra vegada de l''ampolleta!! Espectacular!!', '2025-06-26 09:09:19', '2025-06-26 09:31:19');

-- Immersió 71
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 71, '2025-06-25', '13:30:00', '13:52:00', 3.8, 22, 200, 140, 60, 4, 'bona', 22, 32, 5, 'Tornant de Sant joan i aprofitant que tenia una dia de festa, vaig anar cap a Rovisub a omplir ampolleta. De nou el jordi un crack, me l''omple a 200 (6€). Omplerta i de "cangur" amb els nanos (Jofre i Emma), vaig amb ells cap el balconet. Decideixo provar amb ells l''amplleta. Aigua freda després de bany i Emma i Jofre no aguanten massa i tampoc els super entusiasme. Així que agafo ampolleta i faig volteta a la roca de davant del balconet poquesta estona perqué també agafo fred. Suficient per gaudir de nou per posar el cap sotaigua. Visibilitat boníssima i aigua tranquila. Tot hi així, i estant els nanos, decideixo guardar mitat d''ampolleta i reservar per tornar-hi 20min més el següent dia. No es podria considerar com a immersió, però l''anoto perqué vull contabilitzar les vegades que he entrat a l''aigua fent servir un regulador i ampolleta. I aquesta, n''ha estat també una!! Una meravella! com puc disfrutar inclús d''aquests capbussons tant senzills!? és fàcil, encara que siguin 3m de profunditat, però estàn a 3m quiet, respirant i observant molt quiet les salpetes, ja és una "gozada"... En fi. Llarga vida a l''ampolleta i a tornar-hi 20 minutets més demà o demà passat!! 🙌👏💪💪', '2025-06-26 09:28:24', '2025-06-26 09:28:24');

-- Immersió 72
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 72, '2025-06-27', '15:31:00', '16:10:00', 4.7, 40, 140, 1, 139, 4, 'bona', 25, 32, 7, 'Espectacular Immersioneta! Divendres, teletreballant a Sant Pol amb els meus Pares i Jofre. Acabat de treballar a les 15h, els hi dic als pares i jofre que abans de dinar baixo ràpid a fer 25min màxim del que em quedava d''ampolleta i pujava. Un gustasso! Ni deu al balconet. Aigua neta i boníssima de temperatura (fred zero!!) a diferencia de feia dos dies... no ho entenc, però la temperatura va ser brutal, no baixava dels 25ºC. Agoviadet al principi per bussejar sense romb i contra corrent, vaig arribar a l''escull submergit... mare meva... quina peixera!!! Em quedo estirat a 4.5m quiet, tranquil respirant i de sobte el meu voltant ple de peixets petits, però ple! de sargs, sargs imperials, un parell de neros i al fons mar més endins una barracuda!!!! impressionant, preciós ja que hi havía molt bona visibilitat i temperatura aigua gents freda. En tornar, em quedo per les canyeries observant salpetes i treient backpack i tornant a posar. A l''estar sense fred i molta estona quiet, l''ampolleta entrant a l''aigua entre 140 i 150bar em va durar fins a 40 minuts!! Brutal immersioneta. En serio. Fantàstic!', '2025-06-27 21:36:58', '2025-06-27 21:36:58');

-- Immersió 73
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 73, '2025-06-29', '14:49:00', '15:35:00', 9.0, 46, 200, 1, 199, 4, 'bona', 23, 32, 7, 'Impressionant. Probablement i clarament la millor immersió amb ampolleta de la temporada. Després de marxar migdia després de fer de cangur de pares (pare) a Sant Pol, li dic a la Mare que marxo i que no pateixin pel dinar, que fàcin, que jo ja dinaré tard. Dit i fet, marxo cap a les 11:30 de Sant Pol rumb cap a Blanes. Arribo, i impossible aparcar. Tot a reventar!!! donc varies voltes i cap zona blava lliure... brutal... Marxo cap a Lloret per veure si per allà hi trobo algo, però res. Estic desdesperat, molta estona conduint i res de lloc per arreu!! ple de gent per tot arreu! horrorós! és clar. Dia super caloròs i radiant, Diumenge... i l''hora... impossible!!! Decideixo marxar cap a sant pol i anar a balconet... però intento fer un últim intent a la punta de Sta. Anna, altra vegada per si algún forat... Bingo!!! al ser ja migdia (14h) ja comença a haver-hi algún lloc! Genial, aparco zona blava, i com sempre faig dos viatges, primer deixo mini-parasol instalat a la sorra amb bossa cressi i després torno al cotxe a carregar botella i ploms. Ok, logística fàcil i bona!. Em besteixo ràpid sota umbrella i alucino amb l''aigua! pràcticament ningú! És clar, diumenge tarda centre Blanes-sub tancat, i ni déu... l''aigua, reconet com un llac!!! mai havía vist la punta Santa Anna tant tranquila. Impressioant visibilitat, entro i xal.lo com un boig!! flipo... vaig tirant recorregut fins arribar a l''arquet dels bateigs (6m), després tiro una mica més aball per veure el pessebre amb varies ampolles (9m), em quedo per allà veient salpetes i un parell de Neros maquíssims, i al estar desorientat, fent i pujant a poc a poc, decideixo pujar a superficie al costat d''un niell a punt de sortir de l''aigua... trec el cap molt ràpid i veig que estic orientat més o menys aprop i al costat dret mirant cap a sorra. Torno a baixar i vaig voltant tornant. Altra vegada curiós com segons la direcció que s''agafa, la visibilitat varía moltíssim! curiosíssim. En definitiva, espectacular immersió a tots els nivells on es consolida clarament com a un molt bon reconet per seguir explotant i coneixent. També tinc ganes d''algún moment probar Sa Palomera!! Poter a la propera!? 🙏👌👏🙆‍♂️', '2025-06-30 07:43:46', '2025-06-30 07:54:08');

-- Immersió 74
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 74, '2025-07-05', '13:20:00', '13:59:00', 5.7, 39, 200, 1, 199, 4, 'bona', 23, 30, 7, 'Finalment "Sa Palomera!"... bueeeeeno, una mica decepcionant, molt peladeta, però segurament per una estrena una mica precipitada. Esperant en Roger i l''Anna que vinguèssin a la platja, van arribar tard i vaig passar sól perqué sinó no donaria temps a anar a Cal Tony (14h:30 per dinar). Arribant als niells on hi ha corbs marins, tiro cap a Sa Palomera, visibilitat bona, al no estar orientat i estar a poca profunditat, torno a sortir a superficie a la roca per veure on sóc. És clar, estic al segon niell i encara No havia arribat a Sa Palomera!! orientat, tiro cap a la gran roca i bordejant-la, arribo a un arc preciós (el que havía vist a videos de youtube de nanos passant-lo fent apnea...). L''arc amb contrallums preciós i a poca profunditat (4.5m). L''encaro de terra cap a mar, passant per un petit canó molt xulo. Disfruto i arribo fins els casi 6m fora de l''arc. Observo l''aigua mooooolt més freda que ha superfície. Important termoclina que inclús s''aprecia en la densitat de l''aigua. Roca pelada i visibilitat no massa bona en funció de la direcció. Com que no ho conect, decideixo tornar a passar varies vegades l''arc i NO m''endinso ni provo l''arc que sé que hi ha més endins i bordejant la roca. Segurament en altre ocasió més planificat! torno a passar varies vegades l''arc i tornon cap a la platja i veig roger i anna a l''aigua amb la Núria (ivana i jofre no varen venir, jofre de campaments, i ivana a Barna nit anterior de festa). Estant i jugant una mica amb ells a l''aigua, queda reserva uns 40 bars que després de dinar els passo (14minuts) jugant a la platja. Disfrutant de nou de l''ampolleta, i moooooltes possibilitats de gaudir més de Sa Palomera. Segur que hi tornaré però planificaré més en calma i millor la immersió. Una altre al sac disfrutant moooool!!! 🙌😍👌', '2025-07-05 23:07:58', '2025-07-05 23:07:58');

-- Immersió 75
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 75, '2025-07-27', '08:50:00', '09:25:00', 4.4, 34, 200, 60, 140, 4, 'moderada', 26, 28, 7, 'Senzilla. Dora per agafar aigua calmada després de dies amb vent. Una mica mar de fons i per tant visibilitat afectada però més que suficient. Immersió una mica incòmode i aborrida fins el punt de sortir abans inclús amb la mania de que l''aire tenia una mica de mal gust potser per haver estat a l''ampolla emmagatzemat una mica més d''una setmana. També amb un puntet de mal de cervicals que amb la no molt bona visibilitat m''ha fet sortir sense consumir l''ampolla. Immersió xula per gaudir una mica però fluixa immersió al balconet. No gaire maca, en fi, ja vindràn segur dies millors!', '2025-07-27 17:42:02', '2025-08-04 15:39:33');

-- Immersió 76
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 76, '2025-08-04', '13:31:00', '14:08:00', 3.4, 27, 60, 0, 60, 4, 'moderada', 26, 29, 7, 'No es pot considerar immersió, però com que vaig estar una mica sota aigua, l''enregistro. Sí, essent una immersió pràcticament estàtica molt bé!! Anava de consumir els 60bars, la reserva que m''havia quedat de l''anterior immersió al balconet (que recordo va ser molt aborrida i dolenta...). Molt content, essent una entrada improvisada amb en Jofre, la visibilitat no dolenta (tampoc cap meravella), però quedant-me estàtic a 3m pels voltants de la canyería i aquesta vegada entrant inclús sense semarreta! a pèl, super bé... quedant-me tranquilet veient com les julioles jugaven entre elles movent-se molt ràpid i veien com sempre castanyoletes, sards petits, salpes com sempre "rosegant" roques i quedant-me súper relaxat i tranquilet respirant i observant. M''encanta. Aquesta vegada súper a gust, sense dolor cervical i disfrutant molt com sempre posant el cap sotaigua!!!, i per cert, essent la resta d''aire que feia temps que estava emmagatzemada a l''ampolla, no vaig trobar aquesta vegada gents de mal gust... .Ara amb ampolla buida, a tornar a visitar a en Jordi de Rovisub per omplir a 200bar i provar segur!! una zona que sembla que aquest any pot ser més o menys interessant!! la Roca Grossa!!! a veure si m''ho puc muntar i anar-hi aviat per veure que tal!! fins la propera!! 🙌👏', '2025-08-04 15:38:38', '2025-08-04 15:42:10');

-- Immersió 77
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 77, '2025-08-07', '12:45:00', '13:36:00', 4.7, 51, 200, 1, 199, 4, 'dolenta', 24, 29, 7, 'Altra vegada cap al balconet! És clar, logística fàcil. Amb la Núria treballant, i la ivana sense voler baixar a la platja, quedo amb en Jofre indicant que amb en Gerard i els seus amics vagin cap al costat del balconet (escaletes) perqué jo baixaré amb el carro cap al balconet i per trobar-nos allà. Perfecte. Mar poc mogodeta, poc vent però altra vegada aigua bastant tèrvola. Ni una vegada aquest estiu amb l''aigua super neta i clara!!! una merda... tot i així, suficientment amb visibilitat per gaudir del recurregut comentat en un article del blog sóc Balena. Tiro per canonada, agafo escull enfonsat (cuatre roques) i arribo fins l''espigó on faig busseig estàtic enmig (això sí) de mooooooolts peixets, salpetes petites que m''envolten per tot arreu. Guapíssim. Llàstima de que l''aigua no era super clara!! torno cap enrera reseguint l''escull enfonsat i faig una mica de busseig estàtic contemplant un nero petit. rodejant roquetes trobo un fil amb un plom i el recullo, junt amb una sabata de dona que debia portar força temps. Tornant cap a la canyeria vella, faig busseig estàtic i practico treient-me les ulleres i la caputxa de busseig per tornar-me a posar les ulleres sense caputxa. Comprobo que amb les aletes tornant, quan hi ha cert corrent i onatge és una merda i costa/cansa una mica i en aquest punt sempre m''aborreix ja que demano més aire i és un agobio. Anant tranquil i/o estàtic, és espectacular, per això crec que hauria de trobar, probar zones més estancades sense corrent i amb profunditat. És clar, com sempre, llocs com blanes punta sant anna o qualsevol platja caleta de Calella de Palafrugell són espectaculars. Sense trobar encara doncs el moment de probar roca grossa!! Aquest cap de setmana anem al camping Cypsela de Pals, i la intenció és carregar amplla per endur-me-la i veure si per Illa roja podria fer quelcom. A veure si es donen les circumstàncies i ho puc explicar! De moment avui, malgrat tornar al balconet de sant pol (aquest any amb més sorra i una mica més aborrit), he tornat a disfrutar molt i d''una immersioneta bastant llarga gràcies a la poca profunditat i al busseig estàtic!!! fins la propera!!! 😍👌👌', '2025-08-07 15:06:06', '2025-08-07 15:08:58');

-- Immersió 78
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 78, '2025-08-10', '11:55:00', '12:27:00', 3.3, 32, 200, 120, 80, 4, 'dolenta', 23, 32, 7, 'Cap de setmana de respir (pares pobrets) al camping Cypsela de Pals! El diumenge matí, tenim sort i aparquem al costat de la platja d''Illa Roja (Platja del Recó). Bordejant un camí hi ha roques per on els nanos s''hi tiren. En aquest recorregut amb roques a l''aigua, penso que pot estar bé reseguir-ho. Doncs no. Molt poca profunditat, aigua tèrvola i amb meduses, i molt pelat. Busseig estil espigó Sant Pol o inclús pitjor. Decepció de lloc però que no em treu el gustet de tornar amb l''ampolleta a l''aigua i gaudir del paisatge. No es podría considerar immersió però al estar una mica més de mitja hora fent busseig estàtic i veien salpetes i sards en un cert punt... doncs encara. Si més no, són més minutets que sumen sotaigua! Fluixíssim reconet i immersioneta. Després vaig estar utilitzant ampolleta per "jugar" amb la Ivana i que ho provés una mica. A veure si tasto Roca Grossa! o si faig alguna immersió de veritat abans de que acabi la temporada!! Veurem!', '2025-08-11 09:27:21', '2025-08-11 09:27:21');

-- Immersió 79
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 79, '2025-08-15', '12:50:00', '13:11:00', 6.7, 21, 200, 60, 140, 4, 'moderada', 24, 30, 7, 'Fantàstic dia aniversari 52!!! 🙌😍, com en els últims anys, pujem a Calella Palafrugell a casa els Irazola. Amb els germans, al final anem a la platja tots els nanos l''Albert i Jo, parlem del tema i agafem ampolleta ja que l''havía portat carregada dia abans amb el Jordi (Rovisub). L''Albert marxa fent snorkel amb els nanos i quedo fent immersioneta. Xulíssim. Calella brutal, tot hi així, massa gent i aigua un pél tèrvola per estar massa calenta i amb massa moviment de gent (kayacs, embarcacions, padel surf, taxi zódiac...) un fàstic. Quanta penya! quin horror! tot hi així, em poso entre roques i vaig fent. Fantàstic amb l''ampolleta... 😍 deixo reserva de 50 bars per després provar amb Gibert i Albert. Albert queda flipat i diu molt en serio que se''n vol pillar una (ampolla) per fer això els següents estius... que ho té claríssim!! 😍👏 és clar! em poso súper content, però... sé que és el meu germà i que aixó és la flipada del moment... que després ni se''n recordarà... veurem!! però imagino en que pillem una altre ampolleta i anem junts, ell i/o gibert... per calella provant-ho!!? uau... sería acollonant... veurem!!! en tot cas, dia fantàstic!! matí immersioneta, i després dianant i tertuliant per la tarda porxo casa Irazola... preciós dia!!! 😍😍👌👌🙌🙌', '2025-08-18 09:53:39', '2025-08-18 09:53:39');

-- Immersió 80
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 80, '2025-08-24', '09:01:00', '09:52:00', 5.0, 51, 200, 2, 198, 4, 'dolenta', 25, 26, 7, 'Fantàstica immersió!!! Contra tot pronòstic, i després d''un parell de dies abans haver anat a buscar ampolla nova, li porto al Jordi de Rovisub, se la queda per fer-li les revisions i m''omple la petita (dissabte). Descartant el dissabte, m''animo (costa una mica) a aixecar-me ben dora per anar al Nàutic entrada per espigó i fer immersioneta ben dora per assegurar mar calmat i veure si millora de visibilitat. Entro per la rampa del club nàutic i em vesteixo als peus de l''espigonet. Poquíssima gent, super bé i tranquil perqué força dora. Començo a tirar, i com ja sabia em quedo força estona en els 3m just voltant la punta de l''espigó peque farcidíssim de banc de peixets. ple!!! estirat a terra i contemplant... espectacular. Aigua super calenteta i còmode. Seguint recorregut escull enfonsat denoto d''immediat perdua de visibilitat, bastant dolenta però més que acceptable (no noto gents d''incomoditat) i el que sí al.luciono és en com esta infectadíssim de medusses ou ferrat. A saco per tot arreu!!! moltíssimes! és brutal anar bussejant arran de terra mirant cap amunt a contrallum i veureles totes (moltíssimes!!!) desde abaix i a contrallum. Espectacular! resseguint escull enfonsat observo un nero diria mitjà! brutal... però davant de la no bona visibilitat i la quantitat de meduses, decideixo tornar a on hi ha molts peixets i poca medussa, abans però, tiro una mica endins on hi veig unes pedres soles saltejades. Per sort, veig closques de patxines i imagino pop aprop... efectivament!!!! en una pedra mig enfonsada hi veig un popet ben camuflat... jugo amb ell fins que el faig sortir i el segueixo nedant mentre va tirant tinta negre i buscar una altre roca per camuflar-se canviant de color. Espectacular!!! després de jugar molt amb ell (pobret, reconec estressant-lo) flipo veient-lo amagar-se, escupint tinta, fugint nedant cap a una altre roca.... acollonant!!! en tot això veig com un altre pop petit i simultàniament surt d''una altre roca i marxa nedant fugint!!! acollonant! en tot això, em distrec i veig que em queda molt poc aire... així que els deixo tranquils i marxo cap a l''espigó sortint pel mateix en el club nàutic. 51min d''una immersioneta que degut a els dos pops ha estat la més guapa i en diferència de les de l''estiu amb ampolleta de 4L. Impressionant com he disfrutat!!👌👏😍🙌🙌', '2025-08-24 15:58:40', '2025-08-24 18:53:41');

-- Immersió 81
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 81, '2025-09-06', '13:31:00', '14:35:00', 11.8, 64, 200, 1, 199, 6, 'dolenta', 23, 28, 9, 'Estrena botelleta acer blava de 6L!! Això mateix, dissabte jofre amb plan i Núria em diu que no vol pujar a Sant Pol, pujo doncs sol a buscar l''ampolleta a Rovisub perque m''acabava de passar la revisió periòdica (hidrostàtica, cada 5 anys) i la visual (anual). En jordi com sempre enrolladíssim m''ho deixa per 45€ amb l''ampolleta carregada i sense cobrar-me la càrrega. 🤗👌🙌. Amb regulador cressi modificat, i tot el material decideixo passar-me per Blanes a veure que tal (fàcil logística entrada aigua). Genial, trobo lloc súper aprop del banc del sinofós. Em besteixo i entro a l''aigua. Malgrat no haver-hi massa bona visibilitat (seguim com últim dia! molta medusa ou ferrat! i aigua térvola) però tot i així, super suficient per bussejar molt bé i tranquil. Noto de seguida que vaig massa llastrat. Llògic! acabava de probar nova configuració! posant-me cinturó de 8kg més el quilet de l''arnés, un total de 9Kg amb el neopré fisterra (només pantaló), amb scubapro de camiseta més gorro, noto que vaig amb massa llast, però bussejo igualment. Em costa compensar oïda dret! (primera vegada d''aquest estiu) malgrat això vaig lent recorrent l''espigó i anant baixant molt molt lentament, segueixo amb petita molèstia però suficient per aguantar immersió sense res de mal. Arribo fins la formiga! giro cua i veig com costa tornar enrera per petita corrent, em quedo fent busseig estàtic per allargar i consumir ampolla estant súper tranquil a 4m fent parada seguretat i treient gorro, ulleres i de nou anrés per tornar-ho a posar. Acabo immersió i surto flipat i contentíssim. 64min de nou gaudint com un boig i amb super ampolla!!! super bé amb neopré per allargar temporada!!! 😍😍😍👏👌👌👌, torno cap a barna relaxadet, cotxe, musiqueta i bocata... uau, quin gustasso!! a veure si en faig més amb nova ampolla!! abans d''acabar temporada! 🙏🙏', '2025-09-06 16:35:54', '2025-09-21 20:36:13');

-- Immersió 82
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 82, '2025-09-20', '10:45:00', '11:46:00', 10.3, 61, 200, 5, 195, 6, 'moderada', 22, 27, 7, 'Com comentàva en l''article anterior, la sensació després de provar per primera vegada l''ampolleta de 6L va ser espectacular! Dit i fet, per fortuna, vaig poder muntar-m''ho per fer de nou un puja-baixa cap a Blanes aprofitant que tenia l''ampolla plena per freatic!! de la setmana passada. Sí, vaig voler anar-hi però per mal horrorós de cervicals vaig haver de cancel.lar-la. Després d''una setmana amb l''ampolla plena, aquest passat dissabte dia 20 de setembre vaig poder escapar-me i repetir!  Tirant cap amunt a primera hora, vaig arribar a Blanes i de nou vaig tenir la sort de poder aparcar a zona blava molt aprop del banc del sinofós. Aquesta vegada però, per burro, vaig arriscar en no posar el tiquet (ja estava vestit i carregat) i al tornar, vaig trobar-me la denuncia. Per sort, vaig poder anular-la pagant 10€ de sanció… burro sóc!  Malgrat això, la logística va ser de nou boníssima, i entrant amb d''altres bussejadors de charlie sub (escola costat de Rovi-sub), vaig proposar-me entrar i anar a cercar l''arquet conegut a 6m, junt amb el petit pessebre fet amb dues ampolles.  Tot hi trobar-me marejol i l''aigua una mica remoguda (una mica de mal temps), vaig anar avançant i la visibilitat va anar millorant. La temperatura de l''aigua molt bona i l''opció d''entrar amb el cinturó de llast amb només 6Kg va resultar encertadíssima! molt millor, més lleuger i sense esforços per mantenir-me al fons. Vaig repetir la mateixa fórmula posant-me només la part de baix de fisterra però aquesta vegada m''hi vaig posar també a sota el neopré xaleco sense mànigues del decathlon a més a més de la captuxa. Tot perfecte!! a més a més, aquesta vegada, zero molèstia d''orella!  Avançant cap endins, i passat els primers mini canons, vaig trobar-me amb la "plana" inclinada i després d''una mica de confusió i dubte, vaig trobar de nou cananos més grans per ràpidament anar a parar davant de l''arquet! perfecte!  Després de jugar abans amb una branca de pinassa enfonsada amb un nero entre les branques i pinyes observant un grup de sards cruspinça una medusa ou ferrat morta, vaig seguir endins birant cap a la dreta en direcció a l''escull i direcció a la formiga! en aquesta alçada i ja pensant en tornar (mitja ampolla consumida, indicant 100bar), vaig tenir la sort de tornar a trobar-me amb un pop!!  Jugant de nou amb ell, el vaig deixar tranquil per tornar cap a 4.5m on de nou vaig fer parada de seguretat treient-me màscara, caputxa i tornant a posar màscara! busseig estàtic de nou abans de sortir i arribant als 61 minuts d''immersió!  Ja a la sorra, de nou, somrient i reflexionat sol i a nivell intern de com havia disfrutat altra vegada de l''immersioneta! quin racó! 😍😍 quina fórmula!!', '2025-09-21 20:34:34', '2025-09-21 20:36:54');

-- Immersió 83
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 83, '2026-05-30', '10:50:00', '11:30:00', 5.1, 40, 200, 50, 150, 6, 'bona', 21, 26, 7, 'Primera immersioneta 2026! 😍🙌👌per fi! Divendres 29 per la tarda vaig anar a Freatic, tot bé, accepten ampolla 6L revisada i omplen ampolleta mentre m''espero al cotxe. Pujo a Sant Pol dissabte matí amb Núria (nanos es queden a Barna) i passem el dia. Abans d''anar a la platja amb la Núria, tal i com feia l''any passat, carrego trastos i baixo amb carro cap al balconet. Tot pinta espectacular. Bona aigua, ben plana per dies d''anticicló, i temperatura aigua més que acceptable! em permet, a l''estar a poca profunditat, vestir sense vestit complet. Repeteixo fórmula de xaleco sense mànigues, part baixa de finisterra, i camiseta licra scubapro. També amb caputxa. Entro a l''aigua per on sempre al balconet (aquesta vegada menys pedres perqué més sorra) i començo a bussejar sentint-me súper bé. Com si haugués bussejat el dia anterior!! Malgrat tot, cagada!!! començo a passejar i creient que vaig bé no hi ha manera de que trobi l''escull paralel enfonsat... segueixo tirant passant les tuberies i pensant-me que estàn més enllà. Error!! Fins el punt de que m''entra una mica l''agoviament al veure que estic donant voltes i que no trobo res! ni a la dreta, ni a l''esquerra... no trobo cap pedra... m''agobio i amb por pujo lentament desde 5.1m cap a la superfície (patint una mica per si hi ha barques) i inclús pensant amb malt rollo de pujar tant ràpid. En defintiva pujo fins a dalt amb una mica d''esforça i me n''adono que estic bastant lluny!!! en mig del no res i molt més enllà que l''espigó!! quina cagada!!! situat a superficie torno a baixar i vaig cap a espigó, una vegada allà, força aborrit perqué poca profonditat. A més a més, jugo treient-me l''arnés amb la botella i dedueixo que s''em posa sorra al regulador i començo a perdre aire perque el regulador s''em queda en flux continuo!!! foto un merder de bombolles i pèrdua d''aire acollonant... pujant dels 3m cagant llets de nou cap amunt i tot atabalat com que no puc parar-ho, tanco ampolla. Para el flux continu i vaig nedant cap a la sorra i desde allà donant copets al regulador, torno a comprobar que funciona. A partir d''aqui, veig que queda poc aire, i per tant decideixo fer busseig estàtic  (molt xulo!!) a la roca de 3m que hi ha just d''avant de balconet. Allà m''hi estic una estona i acabo la immersió. Xula (sensacions guapíssimes com sempre) però insatisfet d''haver fallat tant en l''oriantació!!! finalment veig que l''escull està a no més de 3.5m!!! al final el trobo veient que estava al costat i m''havia despistat marxant en direcció tuberies!!! tot i així, disfrutant de nou i preparadíssim per intentar fer-ne moltes de cara a aquest estiu 2026!!!', '2026-05-30 22:12:27', '2026-05-30 22:13:33');

-- Immersió 84
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 84, '2026-06-28', '08:07:00', '09:10:00', 4.8, 63, 190, 40, 150, 6, 'bona', 21, 30, 7, 'Segona immersioneta 2026! Altra vegada al balconet. Arribant dissabte a Sant Pol, ja vaig veure que la mar estava força plana, per tant, prometía. No passant una molt bona nit per molta calor a sant pol, aixecat molt dora, vaig baixar cap al balconet. Ostres, caminar a tres quarts de vuit del matí sense ningú anant direcció al balconet, és fantàstic per tot. Per poca calor, per poca gent... per tot. De fet aquesta vegada vaig voler sortir ja vestit amb el neopré desde casa. Ok va anar molt bé perque el camí és curt i a primera hora no fa tanta calor, i en canvi, estalvio en posar vestit a la sorra on sempre és més incòmode. Perfecte, aquesta vegada sense error, xino xano trobant de seguida l''escull enfonsat. Passejant pel mateix i per tuberires, home, aborridot, poc peix i poca cosa, però xulo per estar relaxat, vaig trobar de nou un plom, i neros petites a entre roques, com sempre. Se''m va passar prou ràpid fent busseig estàtic i estant fins a 63 minuts sense consumir tota l''ampolla! (molt busseig estàtic i sense passar els 5m, és clar). Total, molt bé, però si que hauria de començar a pensar en la propera anar a blanes de nou, ja sigui per fer una punta santa anna, o una sa palomera!!! és a dir, quelcom que en poca distància pugui donar-me ràpidament uns 10m per gaudir una mica de paret, profunditat i a ser possible, més vida. Però fantàstica immersió!! A per la següent!! 🙌👌😊', '2026-06-29 16:01:18', '2026-08-01 18:53:37');

-- Immersió 85
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 85, '2026-07-30', '14:32:00', '15:17:00', 9.4, 45, 200, 40, 160, 6, 'bona', 22, 30, 7, 'Efectivament. Migdia. Dijous entre setmana i en plena hora de dinar. Ni déu. Poca gent. Aigua més que acceptable, vaig anar fent recorregut seguint espigó sense arribar a la formiga (aquest cop no la vaig veure), tot i així, virant cap a l''esquerra, vaig anar passant plana (aburrida) fins trobar ràpidament el famós arquet dels bateigs (es troba a uns 7m). Desde l''arquet, vaig anar tirant cap a nord fins anar agafant més profunditat, cap els 9m.  En aquest punt, i a diferència d''altres vegades, vaig topar amb una paret roca prou maca, recta, profunda fins a 10m on al fons hi havia força posidònia. Ostres quin racó més xulo a Blanes! aquest punt és guapíssim. Definitivament és un lloc ideal per aquest tipus de busseig. Clarament hi tornaré, i m''agradaría acabar dominant molt aquest recó. Me''l vull fer meu i conèixel. És ideal!!  Tot content, vaig estar però poqueta estona a aquesta profunditat però em va permètre veure que hauré d''anar-hi més directe per poder estar més estona i poder disfrutar de la posidònia així com de la paret. Vaig arribar a veure una morena nedant lliurement, també un canó túnel molt agradable per jugar a contra llums i un nero mitja d''una mida prou maca veient-lo també de ben aprop. Espectacular, en serio. molt bé. vaig disfrutar com un boig.  Clarmanent doncs, aquests moments de migdies, fora d''horaris convencionals i de cap de setmana són els millors per gaudir de la punta santa anna. La vull conèixer i dominar molt!!! caldrà doncs anar-hi més sovint! 🙌😍😍👌', '2026-08-02 07:55:59', '2026-08-02 07:55:59');

-- Immersió 86
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 86, '2026-08-01', '09:04:00', '09:59:00', 4.6, 55, 200, 50, 150, 6, 'bona', 23, 30, 7, 'Dit i fet, fantàstic, només amb bañador, licra scubapro, gorro i 2.5mm neopré sense mànigues per prevenir el fred que l''aigua havía baixat una mica. Ostres… després de varies proves, vaig veure que en aquesta convinació NO calen 7kg de llast. Anava massa llastrat! al treure pastilla (sota aigua) i deixar només cinturó amb dues pastilles més el quilet que porta l''arnés… ostra!!! fantàstic!!!  Busseig amb bona visibilitat i veient un parell de neros molt juganers i curiosos mentre feia busseig estàtic. Contrallums brutals amb moles de salpes passant per l''espigonet enfonsat.  És evident que no hi ha color amb blanes, però com a logítica ràpida i seguir estant a l''aigua, és fantàstic, fàcil i ràpid. Un gust. Molt bé!! dues bussejadetes bastant seguides i tirades de preu!! molt content. Part negativa? Esvandint la roba a la font d''en forest, marxo i em deixo i perdo la samarreta licra d''Scubapro!!! putada!!! al tornar ja no hi era. Algún llest ja se l''havia endut. 😥😥😥', '2026-08-02 08:01:35', '2026-08-02 08:01:35');

-- Immersió 87
INSERT INTO immersions (usuari_id, numero_immersio, data, hora_entrada, hora_sortida, profunditat_max, temps_fons, pressio_entrada, pressio_sortida, consum_aire, capacitat_bombona, visibilitat, temp_aigua, temp_aire, pes_llastre, notes, creat_a, actualitzat_a) VALUES ('c0aecf96-9e50-487c-b6ea-cb22c61b8afe', 87, '2026-09-04', '11:38:00', '12:33:00', 5.1, 55, 200, 60, 140, 6, 'bona', 25, 30, 5, 'Dia fantàstic! 😍😍🙌👌vàrem quedar per passar el dia a Sant Pol amb l''Oscar i la Pili. A les 11h ens vam trobar i vàrem baixar a la platja de les barques, molt aprop de l''espigonet perque la intensió era aprofitar l''ampolla que tenia plena desde la setmana passada i gastar-la per l''espigonet i l''escull enfonsat i probar també amb la pili i el oscar la sensació de respirar sotaigua. Cap a dos quarts de dotze vàrem entrar jo amb l''ampolleta i desde l''espigonet, i l''Oscar seguint-me fent snorkel. Vaig conduir-lo cap a l''escoll petit, les roques enfonsades i allà em va dir que marxava i ens vàrem despedir. La visibilitat a l''entrada no massa bona però absolutament suficient. La temperatura aigua caldo. Brutal. Zero fred. Vaig entrar amb banyador, neopré petit semarreta decathlon sense mànigues, gorro. Sobradíssim i inclús el gorro sobrava (però em va molt millor per les ulleres). Flipant súper relaxat i tranquil, per les roques vaig veure un banc bonic de sards i salpes així com un parell de neros, sobre tot un molt encuriosit per la meva presència, és brutal com van prudentment abançant cap a nosaltres. Vaig quedar-me fent busseig estàtic una estona per observar-lo. Disfrutant molt del plaer de rondant per la zona, vaig tornar cap a l''espigonet per veure també molts peixets petits davant les roquetes de la punta de l''espigonet. Sensació espectacular dins de l''aigua amb  poquíssima gent a la platja, un dia espectacular i mar boníssima. Impressionant estar setembre entre setmana (divendres) ja que feia un dia increible, bona companyia (oscar i pili) per acabar dinant un arròs al xirniguito de la platja després de 55min sotaigua gaudint com mai del plaer d''estar sotaigua. No em vull ni imaginar fer el mateix a la Mar Menuda un dia a fora de temporada. Impressionant!!! grandiós dia, i probablement el millor dia de platja de tot l''estiu 2026. Segur. En tots els sentits. Amics, Busseig, dinaret i tartúles!! Impressionant! 🙌👌😍😍. Si ùs plau!!! vull més dies com aquests!!!', '2026-09-05 09:11:31', '2026-09-05 09:12:06');

COMMIT;